// SBA Subject Data (336 questions)
window.QUIZ_DATA = [{"id": 1, "label": "Câu 1", "question": "Which code snippet correctly creates a React-Bootstrap form select control?", "choices": {"A": "<Form.Select> <option>1</option> <option>2</option> </Form.Select>", "B": "<Select> <option>1</option> <option>2</option> </Select>", "C": "<Form.Dropdown> <option>1</option> <option>2</option> </Form.Dropdown>", "D": "<Dropdown> <option>1</option> <option>2</option> </Dropdown>"}, "correct": "A", "correctText": "<Form.Select> <option>1</option> <option>2</option> </Form.Select>", "explanation": "React-Bootstrap dùng Form.Select cho thẻ select và các phần tử option bên trong. Đây là component được thư viện bọc theo kiểu Bootstrap."}, {"id": 2, "label": "Câu 2", "question": "Which lifecycle method in React class components is used for side effects?", "choices": {"A": "componentDidMount", "B": "render", "C": "constructor", "D": "shouldComponentUpdate"}, "correct": "A", "correctText": "componentDidMount", "explanation": "componentDidMount chạy sau khi class component được gắn vào DOM, phù hợp cho tải dữ liệu hoặc đăng ký subscription; cần dọn dẹp khi unmount nếu có đăng ký."}, {"id": 3, "label": "Câu 3", "question": "Which of the following is NOT a valid way to handle events in React?", "choices": {"A": "onClick={handleClick}", "B": "onClick={handleClick()}", "C": "onClick={() => handleClick()}", "D": "onClick={(e) => handleClick(e)}"}, "correct": "B", "correctText": "onClick={handleClick()}", "explanation": "onClick cần nhận một hàm để gọi khi xảy ra sự kiện. Viết handleClick() sẽ chạy ngay lúc render, còn handleClick hoặc hàm arrow sẽ đợi click."}, {"id": 4, "label": "Câu 4", "question": "Which built-in Hook is used to access context values in Functional Components?", "choices": {"A": "useContext()", "B": "useProps()", "C": "useValue()", "D": "useContextValue()"}, "correct": "A", "correctText": "useContext()", "explanation": "useContext (Context) lấy giá trị từ Provider gần nhất phía trên component. Nó giúp truyền dữ liệu xuyên nhiều tầng mà không phải chuyển props thủ công."}, {"id": 5, "label": "Câu 5", "question": "Which hook is an alternative to useState for complex state management?", "choices": {"A": "useMemo", "B": "useReducer", "C": "useRef", "D": "useEffect"}, "correct": "B", "correctText": "useReducer", "explanation": "useReducer phù hợp khi state có nhiều kiểu cập nhật liên quan; reducer tính state mới từ state hiện tại và action được dispatch."}, {"id": 6, "label": "Câu 6", "question": "Which of the following is a valid JSX expression?", "choices": {"A": "<div class=\"my-class\">Hello </div>", "B": "<component style=\"my-style\">World</component>", "C": "<for (let i = 0; i < 5; i++)>Loop</for>", "D": "<if (true) {}?>"}, "correct": "A", "correctText": "<div class=\"my-class\">Hello</div>", "explanation": "JSX cho phép viết cấu trúc thẻ gần giống HTML bên trong JavaScript; khi viết React thông thường nên dùng className thay cho class. Vòng for hoặc if không thể đặt làm tên thẻ như các lựa chọn kia."}, {"id": 7, "label": "Câu 7", "question": "What is the purpose of a custom Hook?", "choices": {"A": "To replace built-in Hooks.", "B": "To share stateful logic between components.", "C": "To define CSS styles.", "D": "To manage database connections."}, "correct": "B", "correctText": "To share stateful logic between components.", "explanation": "Custom Hook là hàm bắt đầu bằng use, dùng để đóng gói và tái sử dụng logic có state hoặc các Hook khác giữa nhiều component."}, {"id": 8, "label": "Câu 8", "question": "How is state initialized in a Class Component?", "choices": {"A": "Using useState().", "B": "Using this.setState().", "C": "By assigning a value to this.state in the constructor().", "D": "By using props.state."}, "correct": "C", "correctText": "By assigning a value to this.state in the constructor().", "explanation": "Class component có thể khởi tạo this.state trong constructor (hoặc class field). Sau khi render, cập nhật qua this.setState để React render lại."}, {"id": 9, "label": "Câu 9", "question": "How do you show a success message alert in React-Bootstrap?", "choices": {"A": "<Alert type=\"success\">Message</Alert>", "B": "<Alert variant=\"success\">Message</Alert>", "C": "<Alert style=\"success\">Message</Alert>", "D": "<SuccessAlert>Message</Success Alert>"}, "correct": "B", "correctText": "<Alert variant=\"success\">Message</Alert>", "explanation": "React-Bootstrap dùng prop variant để chọn kiểu giao diện, ví dụ variant=\"success\" tạo alert mang màu trạng thái thành công."}, {"id": 10, "label": "Câu 10", "question": "Which React feature helps prevent unnecessary re-renders in functional components?", "choices": {"A": "React.memo", "B": "shouldComponentUpdate", "C": "PureComponent", "D": "useState"}, "correct": "A", "correctText": "React.memo", "explanation": "React.memo ghi nhớ kết quả render theo props; nếu props không đổi theo phép so sánh nông, React có thể bỏ qua render không cần thiết."}, {"id": 11, "label": "Câu 11", "question": "Which of the following is a valid way to update state in a Class Component?", "choices": {"A": "this.state = {newValue: 'new' };", "B": "this.setState ({newValue: 'new' });", "C": "useState('new');", "D": "state.update({newValue: 'new'});"}, "correct": "B", "correctText": "this.setState({newValue: 'new' });", "explanation": "this.setState() cập nhật state và lập lịch render lại; gán trực tiếp this.state sau khi component đã tạo sẽ không bảo đảm React nhận biết thay đổi."}, {"id": 12, "label": "Câu 12", "question": "What is ReactJS primarily used for?", "choices": {"A": "Creating user interfaces", "B": "Managing relational databases", "C": "Operating systems", "D": "File system operations"}, "correct": "A", "correctText": "Creating user interfaces", "explanation": "React là thư viện xây dựng giao diện từ các component tái sử dụng, cập nhật UI khi props hoặc state thay đổi."}, {"id": 13, "label": "Câu 13", "question": "What is the benefit of using React's Virtual DOM?", "choices": {"A": "Improved database performance", "B": "Faster UI updates by minimizing direct DOM manipulation", "C": "Enhanced server security", "D": "Simplified network configuration"}, "correct": "B", "correctText": "Faster UI updates by minimizing direct DOM manipulation", "explanation": "React dùng mô hình cây phần tử để so sánh thay đổi và cập nhật DOM thực có chọn lọc, giảm nhiều thao tác DOM không cần thiết."}, {"id": 14, "label": "Câu 14", "question": "Which of the following is a core feature of React?", "choices": {"A": "Two-way data binding", "B": "Virtual DOM", "C": "Server-side rendering only", "D": "SQL database integration"}, "correct": "B", "correctText": "Virtual DOM", "explanation": "Virtual DOM là biểu diễn giao diện trong bộ nhớ để React đối chiếu các phiên bản rồi chỉ cập nhật những phần cần thiết ở DOM thực."}, {"id": 15, "label": "Câu 15", "question": "What is the purpose of the dependency array in useEffect?", "choices": {"A": "To define CSS styles.", "B": "To specify when the effect should run.", "C": "To manage database connections.", "D": "To render the UI."}, "correct": "B", "correctText": "To specify when the effect should run.", "explanation": "Dependency array điều khiển thời điểm useEffect chạy lại: [] thường chạy sau mount, còn [x] chạy lại khi x thay đổi."}, {"id": 16, "label": "Câu 16", "question": "In JSX, how do you add a JavaScript variable to a rendered element?", "choices": {"A": "Using double quotes: \"variable\"", "B": "Using angle brackets: <variable>", "C": "Using curly braces: {variable}", "D": "Using parentheses: (variable)"}, "correct": "C", "correctText": "Using curly braces: {variable}", "explanation": "Trong JSX, dấu ngoặc nhọn nhúng biểu thức JavaScript vào phần nội dung hoặc prop, ví dụ <p> {name} </p>."}, {"id": 17, "label": "Câu 17", "question": "What does the \"responsive\" aspect of React-Bootstrap mean?", "choices": {"A": "Components automatically adjust their appearance based on screen size.", "B": "Components can only be used on mobile devices.", "C": "Components require manual adjustment for each screen size.", "D": "Components primarily handle database interactions."}, "correct": "A", "correctText": "Components automatically adjust their appearance based on screen size.", "explanation": "Lưới và breakpoint của Bootstrap thay đổi cách bố trí theo độ rộng màn hình, giúp giao diện thích ứng trên điện thoại và máy tính."}, {"id": 18, "label": "Câu 18", "question": "Why is React-Bootstrap typically used in React projects?", "choices": {"A": "To replace JavaScript entirely.", "B": "To provide pre-built, responsive UI components.", "C": "To manage server-side logic.", "D": "To create database queries."}, "correct": "B", "correctText": "To provide pre-built, responsive UI components.", "explanation": "React-Bootstrap cung cấp các component như Button, Form và Modal với hệ thống style responsive, giảm lượng UI phải viết từ đầu."}, {"id": 19, "label": "Câu 19", "question": "Which of the following is a React-Bootstrap component?", "choices": {"A": "<Button>", "B": "<Service>", "C": "<Router>", "D": "<Data>"}, "correct": "A", "correctText": "<Button>", "explanation": "Button là component giao diện có sẵn của React-Bootstrap, nhận các props như variant và size để định kiểu nút."}, {"id": 20, "label": "Câu 20", "question": "How do you update state in a Functional Component?", "choices": {"A": "By directly modifying the state variable.", "B": "By calling this.setState().", "C": "By calling the setter function returned by useState().", "D": "By using props.setState()."}, "correct": "C", "correctText": "By calling the setter function returned by useState().", "explanation": "useState trả về [state, setState]; gọi hàm setter báo cho React xử lý state mới và render lại khi cần."}, {"id": 21, "label": "Câu 21", "question": "What happens if you directly modify the state variable returned by useState() in a Functional Component?", "choices": {"A": "The component re-renders.", "B": "An error is thrown.", "C": "The change is ignored.", "D": "The component updates, but it is not recommended."}, "correct": "C", "correctText": "The change is ignored.", "explanation": "Gán trực tiếp vào biến state không gọi setter nên React không lên lịch render lại; muốn giao diện cập nhật phải gọi hàm setter do useState trả về."}, {"id": 22, "label": "Câu 22", "question": "In Class Components, state is accessible through:", "choices": {"A": "props.state.", "B": "this.state.", "C": "useState().", "D": "getState()."}, "correct": "B", "correctText": "this.state.", "explanation": "Trong class component, giá trị state được đọc bằng this.state và cập nhật bằng this.setState(). Hook useState chỉ dành cho function component."}, {"id": 23, "label": "Câu 23", "question": "Which of the following is NOT a valid React hook?", "choices": {"A": "useState", "B": "useClass", "C": "useMemo", "D": "useEffect"}, "correct": "B", "correctText": "useClass", "explanation": "React có các Hook chuẩn như useState, useEffect và useMemo, nhưng không có Hook tích hợp tên useClass."}, {"id": 24, "label": "Câu 24", "question": "Which of the following violates the Rules of Hooks?", "choices": {"A": "Calling hooks at the top level of a component", "B": "Calling hooks inside a loop", "C": "Using multiple useState calls", "D": "Calling hooks in custom hooks"}, "correct": "B", "correctText": "Calling hooks inside a loop", "explanation": "Thứ tự gọi Hook phải ổn định qua các lần render; gọi trong vòng lặp hoặc điều kiện có thể làm React gắn nhầm state với Hook."}, {"id": 25, "label": "Câu 25", "question": "Which hook is used to optimize expensive calculations?", "choices": {"A": "useState", "B": "useEffect", "C": "useMemo", "D": "useCallback"}, "correct": "C", "correctText": "useMemo", "explanation": "useMemo lưu giá trị tính toán và chỉ tính lại khi dependency thay đổi, hữu ích cho phép tính tốn kém."}, {"id": 26, "label": "Câu 26", "question": "What is the primary role of a backend server in a typical React application?", "choices": {"A": "To render the React components.", "B": "To store and process data, and handle API requests.", "C": "To define client-side routing.", "D": "To manage local component state."}, "correct": "B", "correctText": "To store and process data, and handle API requests.", "explanation": "Backend xử lý nghiệp vụ, bảo vệ tài nguyên và truy cập cơ sở dữ liệu, đồng thời cung cấp API để React nhận/gửi dữ liệu."}, {"id": 27, "label": "Câu 27", "question": "Which React feature allows writing HTML-like syntax inside JavaScript?", "choices": {"A": "DOM Script", "B": "JSX", "C": "TypeScript", "D": "HTML Parser"}, "correct": "B", "correctText": "JSX", "explanation": "JSX là phần mở rộng cú pháp của JavaScript, cho phép mô tả UI bằng các thẻ gần giống HTML và biểu thức trong ngoặc nhọn."}, {"id": 28, "label": "Câu 28", "question": "What is the main building block used to create UI in React?", "choices": {"A": "Controllers", "B": "Templates", "C": "Components", "D": "Modules"}, "correct": "C", "correctText": "Components", "explanation": "Component đóng gói giao diện và hành vi thành những phần tái sử dụng; một màn hình React thường là cây các component lồng nhau."}, {"id": 29, "label": "Câu 29", "question": "Which hook is used to read values from a React context?", "choices": {"A": "useState()", "B": "useContext()", "C": "useRef()", "D": "useEffect()"}, "correct": "B", "correctText": "useContext()", "explanation": "useContext (Context) lấy giá trị Provider gần nhất trong cây React, giảm việc truyền props qua nhiều tầng trung gian."}, {"id": 30, "label": "Câu 30", "question": "Which rule of hooks is correct?", "choices": {"A": "Hooks inside loops", "B": "Hooks in normal functions", "C": "Hooks at the top level", "D": "Hooks inside conditions"}, "correct": "C", "correctText": "Hooks at the top level", "explanation": "Hook phải được gọi ở cấp cao nhất của function component hoặc custom Hook, không gọi trong if hay vòng lặp để thứ tự Hook luôn nhất quán."}, {"id": 31, "label": "Câu 31", "question": "Which hook manages local component state?", "choices": {"A": "useState()", "B": "useLocalSt ore()", "C": "useMemory ()", "D": "useValue()"}, "correct": "A", "correctText": "useState()", "explanation": "useState lưu state cục bộ của function component và trả về setter để yêu cầu cập nhật state rồi render lại."}, {"id": 32, "label": "Câu 32", "question": "What does useReducer() return?", "choices": {"A": "state and dispatch", "B": "state only", "C": "reducer and state", "D": "dispatch only"}, "correct": "A", "correctText": "state and dispatch", "explanation": "useReducer trả về cặp [state, dispatch]; dispatch gửi action cho reducer để tính state mới."}, {"id": 33, "label": "Câu 33", "question": "What is the main purpose of a custom hook?", "choices": {"A": "Manipulate DOM", "B": "Reuse logic", "C": "Replace Redux", "D": "Handle routing"}, "correct": "B", "correctText": "Reuse logic", "explanation": "Custom Hook đóng gói logic React có thể tái sử dụng, ví dụ trạng thái biểu mẫu hoặc tải API, mà mỗi lần gọi vẫn có state riêng."}, {"id": 34, "label": "Câu 34", "question": "What are props?", "choices": {"A": "Internal state", "B": "External data", "C": "DOM methods", "D": "Component methods"}, "correct": "B", "correctText": "External data", "explanation": "Props là dữ liệu truyền từ component cha xuống component con, ví dụ thuộc tính name trong <User name=\"An\"/>."}, {"id": 35, "label": "Câu 35", "question": "Props in React are:", "choices": {"A": "Mutable", "B": "Read-only", "C": "Write-only", "D": "Temporary"}, "correct": "B", "correctText": "Read-only", "explanation": "Props được coi là bất biến trong component nhận; muốn thay đổi dữ liệu, component cha cần truyền props mới."}, {"id": 36, "label": "Câu 36", "question": "Which type supports lifecycle methods?", "choices": {"A": "Functional", "B": "Hook", "C": "Class", "D": "Stateless"}, "correct": "C", "correctText": "Class", "explanation": "Class component có các lifecycle methods như componentDidMount và component WillUnmount; function component thường dùng Hook."}, {"id": 37, "label": "Câu 37", "question": "Which lifecycle method runs after first render?", "choices": {"A": "componentDidUpdate", "B": "componentDidMount", "C": "component WillUnmount", "D": "constructor"}, "correct": "B", "correctText": "componentDidMount", "explanation": "componentDidMount được gọi sau lần render gắn component vào DOM đầu tiên, thường dùng để tải dữ liệu hoặc đăng ký sự kiện."}, {"id": 38, "label": "Câu 38", "question": "Which attribute required for lists?", "choices": {"A": "id", "B": "index", "C": "value", "D": "key"}, "correct": "D", "correctText": "key", "explanation": "key giúp React nhận diện từng phần tử khi danh sách thêm, xóa hoặc đổi thứ tự; nên dùng ID ổn định thay vì index nếu danh sách biến động."}, {"id": 39, "label": "Câu 39", "question": "element prop defines?", "choices": {"A": "Route style", "B": "URL path", "C": "Component to render", "D": "Request method"}, "correct": "C", "correctText": "Component to render", "explanation": "Prop element của Route nhận React element cần hiển thị khi path khớp, ví dụ element= {<Home/>}."}, {"id": 40, "label": "Câu 40", "question": "Hook for dynamic params?", "choices": {"A": "useLocation ()", "B": "useInfo()", "C": "useParams()", "D": "useRouteM atch()"}, "correct": "C", "correctText": "useParams()", "explanation": "useParams đọc các đoạn động như của path đã khớp rồi cung cấp giá trị đó cho component."}, {"id": 41, "label": "Câu 41", "question": "Component for redirect?", "choices": {"A": "Switch", "B": "Redirect", "C": "Navigate", "D": "Route"}, "correct": "C", "correctText": "Navigate", "explanation": "Navigate chuyển hướng khi component này được render; có thể dùng prop to để chỉ đường dẫn đích."}, {"id": 42, "label": "Câu 42", "question": "Responsive container?", "choices": {"A": ".grid", "B": ".container-fluid", "C": ".box", "D": ".layout"}, "correct": "B", "correctText": ".container-fluid", "explanation": "container-fluid của Bootstrap dùng chiều rộng 100% ở mọi breakpoint; container thông thường có max-width thay đổi theo màn hình."}, {"id": 43, "label": "Câu 43", "question": "Grid layout components?", "choices": {"A": "Box", "B": "Layout", "C": "Row & Col", "D": "GridView"}, "correct": "C", "correctText": "Row & Col", "explanation": "Hệ lưới Bootstrap dùng Row làm hàng và Col làm cột; có thể chọn kích thước cột theo breakpoint như md hoặc lg."}, {"id": 44, "label": "Câu 44", "question": "Bootstrap message component?", "choices": {"A": "WarningPanel", "B": "Alert", "C": "Notice", "D": "Card"}, "correct": "B", "correctText": "Alert", "explanation": "Alert hiển thị thông điệp trạng thái như success, warning hoặc danger, với màu và style do variant quyết định."}, {"id": 45, "label": "Câu 45", "question": "Bootstrap grouped content?", "choices": {"A": "Panel", "B": "Card", "C": "Box", "D": "Group"}, "correct": "B", "correctText": "Card", "explanation": "Card đóng gói các phần nội dung liên quan như tiêu đề, ảnh và mô tả trong một khung UI nhất quán."}, {"id": 46, "label": "Câu 46", "question": "Virtual DOM improves?", "choices": {"A": "SEO", "B": "Server load", "C": "UI render", "D": "Database"}, "correct": "C", "correctText": "UI render", "explanation": "React đối chiếu cây giao diện giữa các lần render rồi cập nhật DOM thực có chọn lọc, giúp thao tác cập nhật UI hiệu quả hơn."}, {"id": 47, "label": "Câu 47", "question": "One-way data binding?", "choices": {"A": "UI updates state", "B": "State updates UI", "C": "One direction", "D": "Auto props"}, "correct": "C", "correctText": "One direction", "explanation": "Trong React, dữ liệu mặc định đi một chiều từ cha sang con qua props; con muốn thay đổi dữ liệu thường gọi callback cha truyền xuống."}, {"id": 48, "label": "Câu 48", "question": "Lifting state up?", "choices": {"A": "Performance", "B": "Share state", "C": "Remove props", "D": "Global state"}, "correct": "B", "correctText": "Share state", "explanation": "Lifting state up là chuyển state lên tổ tiên chung gần nhất để nhiều component con có thể dùng chung một nguồn dữ liệu."}, {"id": 49, "label": "Câu 49", "question": "useRef stores?", "choices": {"A": "Files", "B": "DOM ref", "C": "State", "D": "CSS"}, "correct": "B", "correctText": "DOM ref", "explanation": "useRef trả về object có thuộc tính current; thường gắn vào DOM node để focus input hoặc giữ giá trị không làm render lại."}, {"id": 50, "label": "Câu 50", "question": "Memoize computations?", "choices": {"A": "useCallback", "B": "useEffect", "C": "useMemo", "D": "useReducer"}, "correct": "C", "correctText": "useMemo", "explanation": "useMemo ghi nhớ kết quả phép tính đến khi dependency đổi, tránh tính lại hàm tốn tài nguyên trên mọi render."}, {"id": 51, "label": "Câu 51", "question": "Which Hook is used for memoizing expensive computations?", "choices": {"A": "useMemo()", "B": "useCallback()", "C": "useReducer()", "D": "useRef()"}, "correct": "A", "correctText": "useMemo()", "explanation": "useMemo trả lại kết quả đã lưu nếu dependency không đổi; dùng nó để hạn chế tính toán lại các biểu thức tốn kém."}, {"id": 52, "label": "Câu 52", "question": "What is the purpose of the React-Bootstrap <Container> component?", "choices": {"A": "Manage DB connections", "B": "Provide responsive layout container", "C": "Define CSS", "D": "Replace React Router"}, "correct": "B", "correctText": "Provide responsive layout container", "explanation": "Container của React-Bootstrap tạo khung bố cục responsive dựa trên hệ thống container và breakpoint của Bootstrap."}, {"id": 53, "label": "Câu 53", "question": "Which is a valid way to update state in a Functional Component?", "choices": {"A": "this.state=\"new\"", "B": "this.setState (\"new\")", "C": "const [s,setS]=use State(\"old\"); setS(\"new\");", "D": "state.update(\"new\")"}, "correct": "C", "correctText": "const [s,setS]=us eState(\"old\"); setS(\"new\");", "explanation": "useState trả về setter; gọi setter với giá trị mới thông báo React cập nhật state, khác với gán trực tiếp vào biến state."}, {"id": 54, "label": "Câu 54", "question": "Which tool inspects React component hierarchy/state?", "choices": {"A": "Browser DevTools", "B": "React Developer Tools", "C": "Node debugger", "D": "CSS inspector"}, "correct": "B", "correctText": "React Developer Tools", "explanation": "React Developer Tools cho xem cây component, props, state và hỗ trợ quan sát nguyên nhân render trong trình duyệt."}, {"id": 55, "label": "Câu 55", "question": "What is the purpose of React components?", "choices": {"A": "Create reusable UI blocks", "B": "Handle backend logic", "C": "Manage SQL connections", "D": "Serve HTML from server"}, "correct": "A", "correctText": "Create reusable UI blocks", "explanation": "Component biến từng phần giao diện thành khối có thể cấu hình bằng props và tái sử dụng ở nhiều màn hình."}, {"id": 56, "label": "Câu 56", "question": "Which hook is used to manage internal state?", "choices": {"A": "useState()", "B": "useEffect()", "C": "useMemo()", "D": "useRef()"}, "correct": "A", "correctText": "useState()", "explanation": "useState giữ dữ liệu qua các lần render của function component và trả setter để thay đổi dữ liệu đó."}, {"id": 57, "label": "Câu 57", "question": "Which hook performs side effects?", "choices": {"A": "useCallback()", "B": "useEffect()", "C": "useLayout()", "D": "useData()"}, "correct": "B", "correctText": "useEffect()", "explanation": "useEffect chạy sau render để đồng bộ với hệ thống bên ngoài, ví dụ gọi API, đặt subscription hoặc thêm listener."}, {"id": 58, "label": "Câu 58", "question": "Which hook reads context values?", "choices": {"A": "useParams()", "B": "useContext()", "C": "useRef()", "D": "useReducer()"}, "correct": "B", "correctText": "useContext()", "explanation": "useContext cung cấp giá trị được React Context Provider truyền từ phía trên mà không cần props drilling."}, {"id": 59, "label": "Câu 59", "question": "What does Virtual DOM improve?", "choices": {"A": "SEO", "B": "Database access", "C": "UI performance", "D": "Server rendering"}, "correct": "C", "correctText": "UI performance", "explanation": "Virtual DOM và quá trình đối chiếu giúp React quyết định thay đổi nào cần áp dụng lên DOM thực, giảm thao tác không cần thiết."}, {"id": 60, "label": "Câu 60", "question": "Which annotation maps a primary key?", "choices": {"A": "@Column", "B": "@Id", "C": "@PK", "D": "@Key"}, "correct": "B", "correctText": "@Id", "explanation": "@Id đánh dấu thuộc tính làm khóa chính để JPA nhận diện từng bản ghi; @GeneratedValue có thể cấu hình sinh khóa tự động."}, {"id": 61, "label": "Câu 61", "question": "Which hook returns a mutable object?", "choices": {"A": "useState", "B": "useEffect", "C": "useRef", "D": "useMemo"}, "correct": "C", "correctText": "useRef", "explanation": "useRef trả object ổn định có current có thể thay đổi; sửa current không tự kích hoạt re-render như useState."}, {"id": 62, "label": "Câu 62", "question": "useMemo is used to:", "choices": {"A": "Fetch data", "B": "Cache expensive calculations", "C": "Update DOM", "D": "Navigate"}, "correct": "B", "correctText": "Cache expensive calculations", "explanation": "useMemo lưu kết quả tính toán và chỉ tính lại khi dependency đổi, phù hợp với phép tính nặng trong quá trình render."}, {"id": 63, "label": "Câu 63", "question": "What is Component Scan used for?", "choices": {"A": "Scan for CSS files", "B": "Scan for components/services/c ontrollers", "C": "Scan for databases", "D": "Scan for routers"}, "correct": "B", "correctText": "Scan for components/services/ controllers", "explanation": "@ComponentScan chỉ định package mà Spring quét để tìm các bean có @Component, @Service, @Controller hoặc annotation tương tự."}, {"id": 64, "label": "Câu 64", "question": "What does \"unidirectional data flow\" in React mean?", "choices": {"A": "Data flows only from server to client", "B": "Data is shared globally across all components", "C": "Data flows from parent to child via props", "D": "Data flows only from child to parent"}, "correct": "C", "correctText": "Data flows from parent to child via props", "explanation": "React thường truyền dữ liệu một chiều qua props từ cha xuống con; con yêu cầu cập nhật qua callback thay vì sửa props của cha."}, {"id": 65, "label": "Câu 65", "question": "Which of the following is the correct way to pass props from parent to child in React?", "choices": {"A": "<Child prop=value/>", "B": "<Child{prop} />", "C": "Child.prop = value", "D": "prop.Child = value"}, "correct": "A", "correctText": "<Child prop=value/>", "explanation": "Props được truyền qua thuộc tính JSX trên component con; với biến JavaScript, cú pháp chuẩn là <Child prop= {value} />, còn giá trị chuỗi viết prop=\"value\". Lựa chọn nguồn thiếu dấu ngoặc nhọn."}, {"id": 66, "label": "Câu 66", "question": "What does useEffect do in React?", "choices": {"A": "Modifies props", "B": "Runs side effects like fetching data", "C": "Stores component state", "D": "Renders the component conditionally"}, "correct": "B", "correctText": "Runs side effects like fetching data", "explanation": "useEffect chạy sau render để đồng bộ với hệ thống ngoài React, ví dụ fetch dữ liệu và thiết lập hoặc hủy subscription."}, {"id": 67, "label": "Câu 67", "question": "What is JSX in React?", "choices": {"A": "A programming language", "B": "A template engine", "C": "A syntax extension for JavaScript", "D": "A CSS preprocessor"}, "correct": "C", "correctText": "A syntax extension for JavaScript", "explanation": "JSX mở rộng cú pháp JavaScript để mô tả giao diện dạng thẻ và nhúng biểu thức bằng ngoặc nhọn; nó được build tool chuyển thành các lời gọi tạo phần tử."}, {"id": 68, "label": "Câu 68", "question": "Which hook is used for managing state in a functional component?", "choices": {"A": "useClass", "B": "useEffect", "C": "useState", "D": "useReducer"}, "correct": "C", "correctText": "useState", "explanation": "useState tạo state cho function component và cung cấp setter; khi setter thay đổi state, React sẽ cập nhật UI phù hợp."}, {"id": 69, "label": "Câu 69", "question": "What is the correct way to lift state up in React?", "choices": {"A": "Store state in the child component", "B": "Pass callback from parent to child", "C": "Use Redux", "D": "Store state in a global object"}, "correct": "B", "correctText": "Pass callback from parent to child", "explanation": "Khi hai component con cần chia sẻ state, chuyển state lên cha rồi truyền dữ liệu và callback xuống để con yêu cầu thay đổi."}, {"id": 70, "label": "Câu 70", "question": "Which lifecycle method is replaced by useEffect in functional components?", "choices": {"A": "component WillMount", "B": "componentDidMount", "C": "shouldComponentUpdate", "D": "getDerived StateFromP rops"}, "correct": "B", "correctText": "componentDidMount", "explanation": "useEffect với dependency [] có thể thực hiện công việc sau mount tương tự componentDidMount, nhưng Hook còn hỗ trợ cleanup và chạy lại theo dependency."}, {"id": 71, "label": "Câu 71", "question": "How to update state in React?", "choices": {"A": "Directly assign new value to state", "B": "Use setState or useState setter", "C": "Call render() method", "D": "Use forceUpdate() method"}, "correct": "B", "correctText": "Use setState or useState setter", "explanation": "Class component cập nhật bằng this.setState; function component gọi setter do useState trả về, không nên gán trực tiếp state."}, {"id": 72, "label": "Câu 72", "question": "What is a controlled component in React?", "choices": {"A": "Component that stores data in global variables", "B": "Component that doesn't use state", "C": "Component whose input value is controlled by React state", "D": "Component with internal timer"}, "correct": "C", "correctText": "Component whose input value is controlled by React state", "explanation": "Controlled input lấy value từ React state và cập nhật state qua onChange, khiến state là nguồn dữ liệu duy nhất của giá trị ô nhập."}, {"id": 73, "label": "Câu 73", "question": "Which of the following is true about keys in React lists?", "choices": {"A": "Keys must be random numbers", "B": "Keys help React identify which items changed", "C": "Keys are required only for the first element", "D": "Keys are the same as props"}, "correct": "B", "correctText": "Keys help React identify which items changed", "explanation": "key giúp thuật toán đối chiếu của React xác định phần tử giữ nguyên, bị thêm hoặc bị xóa khi render một danh sách động."}, {"id": 74, "label": "Câu 74", "question": "What is the purpose of React Fragment (<></>)?", "choices": {"A": "Wrap multiple elements without adding extra DOM nodes", "B": "Replace div tags in HTML", "C": "Create new component instances", "D": "Improve routing"}, "correct": "A", "correctText": "Wrap multiple elements without adding extra DOM nodes", "explanation": "React Fragment gom nhiều phần tử con mà không tạo thêm thẻ HTML trong DOM, tránh phá bố cục hoặc cấu trúc bảng."}, {"id": 75, "label": "Câu 75", "question": "Which of the following is NOT a valid React Hook?", "choices": {"A": "useReducer", "B": "useMemo", "C": "useFetch", "D": "useEffect"}, "correct": "C", "correctText": "useFetch", "explanation": "React không cung cấp built-in Hook tên useFetch; dự án có thể tự tạo custom Hook này để đóng gói việc tải dữ liệu."}, {"id": 76, "label": "Câu 76", "question": "Which statement is true about useState?", "choices": {"A": "It can only store numbers", "B": "It returns the state value and a function to update it", "C": "It is used only in class components", "D": "It creates side effects"}, "correct": "B", "correctText": "It returns the state value and a function to update it", "explanation": "useState(ini tialValue) trả một mảng gồm state hiện tại và hàm setter; setter kích hoạt quá trình cập nhật state của React."}, {"id": 77, "label": "Câu 77", "question": "In React, how do you conditionally render content?", "choices": {"A": "Using if-else outside JSX", "B": "Using ternary operator or && in JSX", "C": "Using switch-case only", "D": "React does not support conditional rendering"}, "correct": "B", "correctText": "Using ternary operator or && in JSX", "explanation": "Có thể dùng toán tử ba ngôi condition? A: B hoặc condition && A trong JSX để quyết định phần giao diện hiển thị."}, {"id": 78, "label": "Câu 78", "question": "What is the virtual DOM in React?", "choices": {"A": "A browser feature", "B": "An actual copy of the DOM", "C": "A lightweight copy of the real DOM used for performance", "D": "A styling framework"}, "correct": "C", "correctText": "A lightweight copy of the real DOM used for performance", "explanation": "Virtual DOM là cách gọi phổ biến cho biểu diễn cây phần tử React trong bộ nhớ; React so sánh cây để cập nhật DOM thật có chọn lọc."}, {"id": 79, "label": "Câu 79", "question": "Which method is used to pass data from child to parent in React?", "choices": {"A": "Using props", "B": "Using callbacks passed from parent", "C": "Using context", "D": "Direct variable reference"}, "correct": "B", "correctText": "Using callbacks passed from parent", "explanation": "Luồng dữ liệu mặc định đi xuống theo props; để con gửi thông tin lên cha, cha truyền một hàm callback và con gọi hàm với dữ liệu."}, {"id": 80, "label": "Câu 80", "question": "Which hook is used for performance optimization by memoizing values?", "choices": {"A": "useEffect", "B": "useState", "C": "useMemo", "D": "useReducer"}, "correct": "C", "correctText": "useMemo", "explanation": "useMemo lưu kết quả tính toán dựa trên dependencies, giúp hạn chế chạy lại logic tốn kém qua các lần render."}, {"id": 81, "label": "Câu 81", "question": "What does lifting state up mean in React?", "choices": {"A": "Moving state from parent to child", "B": "Moving state to global context", "C": "Moving state to the nearest common ancestor", "D": "Moving state to Redux store"}, "correct": "C", "correctText": "Moving state to the nearest common ancestor", "explanation": "Lifting state up nghĩa là đưa state lên tổ tiên chung gần nhất của các component cần dùng chung, rồi truyền xuống bằng props."}, {"id": 82, "label": "Câu 82", "question": "Which of the following is true about controlled components?", "choices": {"A": "Their state is managed by the DOM", "B": "Their state is managed by React", "C": "They use refs to access values", "D": "They can't be used in forms"}, "correct": "B", "correctText": "Their state is managed by React", "explanation": "Controlled component nhận giá trị input từ React state và thông báo thay đổi qua onChange; nó không tự quản lý giá trị chỉ bằng DOM."}, {"id": 83, "label": "Câu 83", "question": "How do you access route parameters in a component rendered by React Router v6?", "choices": {"A": "Using this.props.params.", "B": "Using useParams() Hook.", "C": "Using props.match.params.", "D": "Using context params."}, "correct": "B", "correctText": "Using useParams() Hook.", "explanation": "useParams() đọc các tham số động trong URL, ví dụ /users/sẽ trả về id.React Router v6 không còn cách dùng props.match.params như v5."}, {"id": 84, "label": "Câu 84", "question": "What is a key advantage of client-side routing?", "choices": {"A": "Improved SEO.", "B": "Faster initial page load times.", "C": "Smoother user experience due to reduced server requests.", "D": "Enhanced server security."}, "correct": "C", "correctText": "Smoother user experience due to reduced server requests.", "explanation": "Client-side routing thay đổi màn hình theo URL mà không tải lại toàn bộ tài liệu HTML, nên thao tác điều hướng thường mượt và giảm yêu cầu tải trang."}, {"id": 85, "label": "Câu 85", "question": "How do you create navigation links in a React-Bootstrap Navbar?", "choices": {"A": "<NavLink>", "B": "<Nav.Link>", "C": "<Link>", "D": "<Anchor>"}, "correct": "B", "correctText": "<Nav.Link>", "explanation": "Trong React-Bootstrap, component chuẩn để tạo liên kết trong Navbar là <Nav.Link>. Thẻ <NavLink> thường thuộc thư viện react-router-dom."}, {"id": 86, "label": "Câu 86", "question": "How do you handle 404 Not Found pages in React Router? <Routes> <Route path=\"/\" element= {<Home />}/> <Route path=\"/about\" element= {<About />}/> <Route path=\"\" element= {<NotFound/>} /> </Routes>", "choices": {"A": "By using the <NotFound> component.", "B": "By adding a <Route path=\"\" element= {<NotFound/>} /> as the last route.", "C": "By using the notFound prop on the <Routes> component.", "D": "By using the useNotFound() hook."}, "correct": "B", "correctText": "By adding a <Route path=\"\" element= {<NotFound />} /> as the last route.", "explanation": "Route có path=\"\" bắt các đường dẫn không khớp route khác và render NotFound.Trong React Router v6, bộ định tuyến tự chọn route phù hợp nhất."}, {"id": 87, "label": "Câu 87", "question": "How do you define a route parameter in a React Router path?", "choices": {"A": "Using square brackets: [param]", "B": "Using curly braces: {param}", "C": "Using a colon::param", "D": "Using a question mark:? param"}, "correct": "C", "correctText": "Using a colon::param", "explanation": "Đặt dấu hai chấm trước tên biến trong path, ví dụ /users/, để khai báo tham số động; đọc nó bằng useParams()."}, {"id": 88, "label": "Câu 88", "question": "Which router wraps app?", "choices": {"A": "RouterProvider", "B": "BrowserRouter", "C": "PageRouter", "D": "Route"}, "correct": "B", "correctText": "BrowserRouter", "explanation": "BrowserRouter đồng bộ URL với lịch sử trình duyệt, tạo ngữ cảnh định tuyến cho Routes, Link và các Hook của React Router."}, {"id": 89, "label": "Câu 89", "question": "Which component holds routes?", "choices": {"A": "RouteList", "B": "Switch", "C": "Routes", "D": "Router"}, "correct": "C", "correctText": "Routes", "explanation": "Routes chứa các Route và chọn phần tử phù hợp với đường dẫn hiện tại trong React Router v6."}, {"id": 90, "label": "Câu 90", "question": "Hook for navigation?", "choices": {"A": "useRoute()", "B": "useNavigate()", "C": "useNavLink()", "D": "useSwitch()"}, "correct": "B", "correctText": "useNavigate()", "explanation": "useNavigate trả về hàm navigate để chuyển URL trong handler hoặc effect, chẳng hạn navigate('/login')."}, {"id": 91, "label": "Câu 91", "question": "Advantage of SPA?", "choices": {"A": "Full reload", "B": "Fast navigation", "C": "No JS", "D": "Better SEO"}, "correct": "B", "correctText": "Fast navigation", "explanation": "SPA thường chỉ tải tài liệu HTML chính một lần, sau đó thay nội dung bằng JavaScript khi chuyển trang, nên điều hướng mượt hơn."}, {"id": 92, "label": "Câu 92", "question": "CSR describes?", "choices": {"A": "Server renders HTML", "B": "Browser renders UI", "C": "HTML by PHP", "D": "Rendering only server"}, "correct": "B", "correctText": "Browser renders UI", "explanation": "Client-Side Rendering (CSR) tạo/ cập nhật giao diện ngay trong trình duyệt bằng JavaScript; SSR dựng HTML ở server trước."}, {"id": 93, "label": "Câu 93", "question": "Render child routes?", "choices": {"A": "Children", "B": "Outlet", "C": "Render", "D": "Next"}, "correct": "B", "correctText": "Outlet", "explanation": "Outlet là vị trí hiển thị element của route con đã khớp trong layout của route cha."}, {"id": 94, "label": "Câu 94", "question": "In React Router v6 which component is used to programma tically navigate to a different route?", "choices": {"A": "<Link>", "B": "<Route>", "C": "<Switch>", "D": "<Navigate>"}, "correct": "D", "correctText": "<Navigate>", "explanation": "Navigate thực hiện điều hướng khi được render trong JSX, ví dụ <Navigate to=\"/login\"/>. Nếu muốn gọi chuyển trang từ một hàm sự kiện, dùng useNavigate()."}, {"id": 95, "label": "Câu 95", "question": "What is a key advantage of server-side routing?", "choices": {"A": "Faster CSR", "B": "Better SEO and initial page load", "C": "Reduced server load", "D": "Simplified client code"}, "correct": "B", "correctText": "Better SEO and initial page load", "explanation": "Server-side routing trả HTML thích hợp cho từng URL ngay từ server, thuận lợi cho bot lập chỉ mục và hiển thị nội dung ban đầu."}, {"id": 96, "label": "Câu 96", "question": "What is the benefit of using <Link> over <a> in React Router?", "choices": {"A": "Full page reload", "B": "Prevent reload & allow client-side routing", "C": "<a> handles routing automatically", "D": "No difference"}, "correct": "B", "correctText": "Prevent reload & allow client-side routing", "explanation": "Link của React Router chuyển route qua history API, tránh tải lại trang HTML; thẻ a thông thường sẽ điều hướng tải tài liệu mới."}, {"id": 97, "label": "Câu 97", "question": "Which file defines all main routes in React Router v6?", "choices": {"A": "App.js", "B": "index.js", "C": "routes.js", "D": "AppRoutes.jsx"}, "correct": "D", "correctText": "AppRoutes.jsx", "explanation": "AppRoutes.jsx có thể là tệp tự tạo để gom định nghĩa route trong một dự án; React Router không bắt buộc tên tệp này, route có thể nằm trong nhiều tệp khác."}, {"id": 98, "label": "Câu 98", "question": "Which React Router component renders child routes?", "choices": {"A": "<Child>", "B": "<Outlet>", "C": "<SubRoute>", "D": "<Switch>"}, "correct": "B", "correctText": "<Outlet>", "explanation": "Outlet là nơi route cha chèn phần giao diện của route con khớp URL, giúp tổ chức nested layouts."}, {"id": 99, "label": "Câu 99", "question": "What is a SPA?", "choices": {"A": "An app that reloads pages", "B": "A single HTML shell updated dynamically", "C": "A backend REST API", "D": "An SSR-only site"}, "correct": "B", "correctText": "A single HTML shell updated dynamically", "explanation": "SPA khởi tạo một trang HTML chính và thay đổi nội dung động bằng JavaScript khi người dùng thao tác, không cần tải lại toàn bộ trang mỗi lần."}, {"id": 100, "label": "Câu 100", "question": "What is the main limitation of SPA?", "choices": {"A": "Slow navigation", "B": "Poor SEO if not optimized", "C": "No CSS", "D": "Cannot call APIs"}, "correct": "B", "correctText": "Poor SEO if not optimized", "explanation": "SPA dựng UI bằng JavaScript ở client có thể khiến crawler khó lấy nội dung nếu không có SSR/prerender, vì thế SEO cần được tối ưu riêng."}, {"id": 101, "label": "Câu 101", "question": "SPA navigation is handled by:", "choices": {"A": "Browser reload", "B": "Server redirect", "C": "Client-side routing", "D": "SQL triggers"}, "correct": "C", "correctText": "Client-side routing", "explanation": "Trong SPA, router ở browser đổi component theo URL mà không tải lại trang HTML; server thường chỉ phục vụ API và trang ban đầu."}, {"id": 102, "label": "Câu 102", "question": "Which React element creates navigation links?", "choices": {"A": "<A>", "B": "<Link>", "C": "<NavButton>", "D": "<Route>"}, "correct": "B", "correctText": "<Link>", "explanation": "Link tạo liên kết chuyển route trong ứng dụng React Router mà tránh full page reload theo cơ chế điều hướng client."}, {"id": 103, "label": "Câu 103", "question": "Which component renders one route at a time in React Router v5?", "choices": {"A": "<Routes>", "B": "<Switch>", "C": "<Outlet>", "D": "<Redirect>"}, "correct": "B", "correctText": "<Switch>", "explanation": "Switch của React Router v5 render Route khớp đầu tiên; ở v6, component tương ứng là Routes với cơ chế xếp hạng route."}, {"id": 104, "label": "Câu 104", "question": "Which package is commonly used for routing in React applications?", "choices": {"A": "react-navigation", "B": "react-router-dom", "C": "react-router-native", "D": "react-router-core"}, "correct": "B", "correctText": "react-router-dom", "explanation": "react-router-dom cung cấp các component và Hook định tuyến cho ứng dụng React trên web, như BrowserRouter, Link và useNavigate trong v6."}, {"id": 105, "label": "Câu 105", "question": "How do SPAs affect analytics and tracking tools like Google Analytics?", "choices": {"A": "Analytics tools natively support SPAs without setup", "B": "They simplify tracking because everything is on one page", "C": "SPAs automatically log page views", "D": "They require manual tracking for route changes"}, "correct": "D", "correctText": "They require manual tracking for route changes", "explanation": "SPA thay đổi route mà không tải lại toàn bộ trang, nên công cụ analytics có thể không tự ghi pageview mới; cần theo dõi chuyển route và gửi sự kiện thủ công."}, {"id": 106, "label": "Câu 106", "question": "Which of the following is TRUE about React Router v6?", "choices": {"A": "Route components are automatically lazy-loaded", "B": "React Router only supports hash-based routing", "C": "<Switch> is still used to group routes", "D": "Routes must be wrapped in <Router> or <BrowserRouter>"}, "correct": "D", "correctText": "Routes must be wrapped in <Router>or <BrowserRouter>", "explanation": "Routes và Route cần nằm trong ngữ cảnh router như BrowserRouter để đọc location và lịch sử điều hướng."}, {"id": 107, "label": "Câu 107", "question": "Which of the following best explains why SPAs provide a better user experience?", "choices": {"A": "They enable seamless navigation without full reloads", "B": "They are always faster than any server-rendered app", "C": "They use server-side rendering for every page", "D": "They refresh the entire browser page on each request"}, "correct": "A", "correctText": "They enable seamless navigation without full reloads", "explanation": "SPA tránh full page reload khi chuyển route, giúp giữ state và cập nhật phần nội dung cần thiết thay vì dựng lại toàn bộ trang."}, {"id": 108, "label": "Câu 108", "question": "What is the purpose of the <Outlet/> component in nested routes?", "choices": {"A": "It renders the matched child route element", "B": "It fetches external data", "C": "It acts as a fallback route", "D": "It redirects to the home page"}, "correct": "A", "correctText": "It renders the matched child route element", "explanation": "Outlet trong route cha đánh dấu vị trí render route con đã khớp, giúp dùng chung layout như menu và footer."}, {"id": 109, "label": "Câu 109", "question": "What is one disadvantage of SPAs in terms of browser history and navigation?", "choices": {"A": "They provide better back/forward navigation than traditional sites", "B": "They cannot support routing", "C": "They use standard browser navigation without modification", "D": "Manual configuration is needed to manage browser history correctly"}, "correct": "D", "correctText": "Manual configuration is needed to manage browser history correctly", "explanation": "Khi tự thiết kế SPA, cần đồng bộ trạng thái URL và lịch sử trình duyệt để back/forward hoạt động đúng; thư viện router hỗ trợ phần lớn việc này."}, {"id": 110, "label": "Câu 110", "question": "Which of the following is used to handle routing in React apps?", "choices": {"A": "React DOM", "B": "React Router", "C": "React Navigation", "D": "React Redux"}, "correct": "B", "correctText": "React Router", "explanation": "React Router nối URL với component cần render, cung cấp Link, Routes, useParams và nhiều công cụ quản lý điều hướng."}, {"id": 111, "label": "Câu 111", "question": "In React Router, what does the <Switch> component do?", "choices": {"A": "Groups multiple routes", "B": "Switches between states", "C": "Renders the first matching route", "D": "Used to toggle views"}, "correct": "C", "correctText": "Renders the first matching route", "explanation": "Trong React Router v5, Switch render Route khớp đầu tiên, tránh nhiều Route cùng khớp đồng thời; v6 dùng Routes."}, {"id": 112, "label": "Câu 112", "question": "Why are SPAs considered ideal for building responsive web applications?", "choices": {"A": "They automatically convert to mobile apps", "B": "They provide dynamic and fast content updates", "C": "They completely avoid CSS", "D": "They can only be accessed on mobile devices"}, "correct": "B", "correctText": "They provide dynamic and fast content updates", "explanation": "SPA cập nhật phần nội dung động thay vì tải toàn bộ trang khi đổi view, giúp tương tác nhanh và tạo cảm giác phản hồi liên tục."}, {"id": 113, "label": "Câu 113", "question": "How do SPAs typically reduce server load?", "choices": {"A": "By disabling server-side APIs", "B": "By caching everything on the server", "C": "By offloading routing and rendering to the client", "D": "By avoiding use of databases"}, "correct": "C", "correctText": "By oQoading routing and rendering to the client", "explanation": "SPA xử lý phần lớn việc đổi route và dựng giao diện ở browser, nên server không phải gửi toàn bộ HTML cho mỗi lần chuyển màn hình; API vẫn cần xử lý dữ liệu."}, {"id": 114, "label": "Câu 114", "question": "What is the benefit of using <Link> over traditional anchor (<a>) tags in React Router?", "choices": {"A": "<Link> triggers a full page reload.", "B": "<Link> prevents a full page reload and allows client-side routing.", "C": "<a> tags automatically handle client-side routing.", "D": "There is no benefit; they are interchangeable."}, "correct": "B", "correctText": "<Link> prevents a full page reload and allows client-side routing.", "explanation": "Link của React Router xử lý client-side navigation và cập nhật URL mà không reload toàn trang; thẻ a thông thường làm trình duyệt tải tài liệu mới."}, {"id": 115, "label": "Câu 115", "question": "What is the core feature of Node.js that makes it efficient for handling concurrent requests?", "choices": {"A": "Multi-threading", "B": "Blocking I/O", "C": "Event-driven, non-blocking I/O", "D": "Relational databases"}, "correct": "C", "correctText": "Event-driven, non-blocking I/O", "explanation": "Event loop của Node.js xử lý callback, kết hợp I/O bất đồng bộ không chặn luồng chính khi đợi mạng hoặc ổ đĩa. Công việc CPU nặng vẫn có thể chặn event loop."}, {"id": 116, "label": "Câu 116", "question": "How do you typically handle asynchronous data fetching in a React component?", "choices": {"A": "By directly modifying the DOM", "B": "By using lifecycle methods (Class Components) or useEffect Hook (Functional Components)", "C": "By using CSS selectors", "D": "By using global variables"}, "correct": "B", "correctText": "By using lifecycle methods (Class Components) or useEffect Hook (Functional Components)", "explanation": "Có thể tải dữ liệu sau khi component xuất hiện bằng componentDidMount ở class hoặc useEffect ở function.Cần xử lý Promise và trạng thái loading/error."}, {"id": 117, "label": "Câu 117", "question": "What is Axios primarily used for in JavaScript applications?", "choices": {"A": "To define CSS styles.", "B": "To make HTTP requests.", "C": "To manage database connections.", "D": "To handle client-side rendering exclusively."}, "correct": "B", "correctText": "To make HTTP requests.", "explanation": "Axios là HTTP client dựa trên Promise, có các hàm get/post/put/delete và thường tự chuyển JSON response thành object JavaScript."}, {"id": 118, "label": "Câu 118", "question": "Which keyword is used to pause the execution of an async function until a Promise is resolved?", "choices": {"A": "async", "B": "promise", "C": "await", "D": "callback"}, "correct": "C", "correctText": "await", "explanation": "await tạm dừng việc thực thi bên trong async function cho đến khi Promise hoàn tất; nó không chặn toàn bộ event loop."}, {"id": 119, "label": "Câu 119", "question": "What is the syntax for creating a new Promise?", "choices": {"A": "new Promise(callback)", "B": "createPromise(callback)", "C": "Promise.create(callback)", "D": "Promise.new(callback)"}, "correct": "A", "correctText": "new Promise(callback)", "explanation": "new Promise(executor) tạo Promise, trong đó executor nhận resolve và reject để báo thành công hoặc thất bại của tác vụ bất đồng bộ."}, {"id": 120, "label": "Câu 120", "question": "Which hook is used for performing side effects such as data fetching?", "choices": {"A": "useEffect()", "B": "useCallback()", "C": "useMemo()", "D": "useLayoutEffect()"}, "correct": "A", "correctText": "useEffect()", "explanation": "useEffect thực hiện side effect sau render như tải dữ liệu, đăng ký sự kiện hoặc đồng bộ với dịch vụ bên ngoài."}, {"id": 121, "label": "Câu 121", "question": "Realtime tech?", "choices": {"A": "Axios", "B": "Fetch", "C": "WebSockets", "D": "HTTP GET"}, "correct": "C", "correctText": "WebSockets", "explanation": "WebSocket duy trì kết nối hai chiều để client và server chủ động trao đổi dữ liệu thời gian thực, thay vì liên tục gửi HTTP GET."}, {"id": 122, "label": "Câu 122", "question": "Parse JSON using Fetch?", "choices": {"A": "parseJson()", "B": "toJSON()", "C": "text()", "D": "json()"}, "correct": "D", "correctText": "json()", "explanation": "Response của Fetch có phương thức json() đọc body và phân tích JSON, trả về một Promise chứa dữ liệu đã parse."}, {"id": 123, "label": "Câu 123", "question": "Advantage of Axios?", "choices": {"A": "No promises", "B": "Auto JSON parsing", "C": "UI elements", "D": "No JS needed"}, "correct": "B", "correctText": "Auto JSON parsing", "explanation": "Axios thường tự phân tích JSON response theo cấu hình mặc định; dữ liệu có thể truy cập qua response.data."}, {"id": 124, "label": "Câu 124", "question": "Which of the following is a valid way to handle a Promise rejection?", "choices": {"A": "promise.error(err => {})", "B": "promise.reject(err => {})", "C": "promise.catch(err => {})", "D": "promise.fail(err => {})"}, "correct": "C", "correctText": "promise.catch(err => {})", "explanation": "Promise bị reject có thể được bắt bằng .catch(error => ...), nhờ đó ứng dụng xử lý lỗi thay vì để rejection không được xử lý."}, {"id": 125, "label": "Câu 125", "question": "Which of the following is the correct way to handle a successful fetch request?", "choices": {"A": "fetch(url).then(response => response.json()).then(data => console.log(data));", "B": "fetch(url).then(data => data.json()).then(console.log(data));", "C": "fetch(url).data().then(console.log);", "D": "fetch(url).json().then(data => console.log(data));"}, "correct": "A", "correctText": "fetch(url).then(response => response.json()).then(data => console.log(data));", "explanation": "fetch() trả về Promise chứa Response; cần gọi response.json() để đọc JSON rồi dùng .then() tiếp theo để xử lý dữ liệu."}, {"id": 126, "label": "Câu 126", "question": "How do you send POST data using Axios?", "choices": {"A": "axios.write('url', data)", "B": "axios.sendPost('url', data)", "C": "axios.post('url', data)", "D": "axios.get('url', data)"}, "correct": "C", "correctText": "axios.post('url', data)", "explanation": "axios.post(url, data) gửi request POST với data làm request body, thường được chuyển thành JSON khi truyền object thông thường."}, {"id": 127, "label": "Câu 127", "question": "What is returned by an Axios request?", "choices": {"A": "String", "B": "Object", "C": "Array", "D": "Promise"}, "correct": "D", "correctText": "Promise", "explanation": "Axios trả về Promise; khi thành công nhận AxiosResponse có data, status và headers, khi lỗi Promise bị reject."}, {"id": 128, "label": "Câu 128", "question": "What does the fetch() function in JavaScript return?", "choices": {"A": "An XMLHttpRequest object", "B": "A Promise", "C": "A callback function", "D": "A JSON object"}, "correct": "B", "correctText": "A Promise", "explanation": "fetch() trả Promise được resolve thành Response khi có HTTP response; trạng thái 4xx/5xx không tự làm Promise reject, cần kiểm tra response.ok."}, {"id": 129, "label": "Câu 129", "question": "How can you handle errors in an Axios request?", "choices": {"A": "Using .error()", "B": "Using .catch()", "C": "Using .handle()", "D": "Using .fail()"}, "correct": "B", "correctText": "Using .catch()", "explanation": "Axios Promise có thể bắt lỗi bằng .catch(error) hoặc try/catch với await; phân biệt error.response và error.request để xử lý rõ ràng."}, {"id": 130, "label": "Câu 130", "question": "How can you set a default base URL in Axios?", "choices": {"A": "axios.defaults.baseURL = 'https://api.example.com'", "B": "axios.configure.baseURL = 'https://api.example.com'", "C": "axios.setBaseURL('https://api.example.com')", "D": "axios.baseURL('https://api.example.com')"}, "correct": "A", "correctText": "axios.defaults.baseURL = 'https://api.example.com'", "explanation": "axios.defaults.baseURL đặt tiền tố URL chung cho các request dùng instance mặc định; nhờ đó có thể gọi axios.get('/users') thay vì lặp địa chỉ server."}, {"id": 131, "label": "Câu 131", "question": "Which of the following is the correct way to make a GET request using Axios?", "choices": {"A": "axios.get('https://api.example.com/data')", "B": "axios.send('GET', 'https://api.example.com/data')", "C": "axios.fetch('https://api.example.co m/data')", "D": "fetch.axios('https://api.example.co m/data')"}, "correct": "A", "correctText": "axios.get('https://api.example.co m/data')", "explanation": "axios.get(u rl) gửi HTTP GET và trả về Promise chứa response; dữ liệu server trả về thường truy cập qua response.data."}, {"id": 132, "label": "Câu 132", "question": "Which REST principle ensures that each request from a client to a server must contain all of the information needed to understand and process the request?", "choices": {"A": "Layered System", "B": "Code on Demand", "C": "Stateless", "D": "Cacheable"}, "correct": "C", "correctText": "Stateless", "explanation": "Stateless yêu cầu mỗi request chứa đủ dữ liệu để máy chủ xử lý, không phụ thuộc trạng thái của request trước. Điều này giúp mở rộng nhiều máy chủ dễ hơn."}, {"id": 133, "label": "Câu 133", "question": "How do you typically handle errors when making requests to a RESTful API using Axios in a ReactJS application?", "choices": {"A": "By ignoring the error", "B": "By using.catch() on the Axios promise and accessing the error object", "C": "By using static HTML error messages", "D": "By redirecting to a different page without displaying an error"}, "correct": "B", "correctText": "By using.catch () on the Axios promise and accessing the error object", "explanation": "Axios trả về Promise; có thể bắt lỗi bằng .catch(error => ...), hoặc try/catch khi dùng await.error.response giúp xem mã HTTP khi máy chủ phản hồi lỗi."}, {"id": 134, "label": "Câu 134", "question": "Which of the following is a common approach to handling cross-origin requests (CORS) between React and Spring Boot?", "choices": {"A": "Disabling security in React.", "B": "Configuring CORS in Spring Boot.", "C": "Using server-side rendering exclusively.", "D": "Using iframes to embed the Spring Boot application."}, "correct": "B", "correctText": "Configuring CORS in Spring Boot.", "explanation": "CORS được trình duyệt kiểm tra theo các header máy chủ trả về; Spring Boot có thể cấu hình bằng @CrossOrigin hoặc WebMvcConfigurer để cho phép origin của React."}, {"id": 135, "label": "Câu 135", "question": "Which annotation is used to provide a summary and description for a specific API endpoint or method in a controller?", "choices": {"A": "@Description", "B": "@RequestMapping", "C": "@Operation", "D": "@Endpoint Des"}, "correct": "C", "correctText": "@Operation", "explanation": "@Operation của OpenAPI mô tả summary, description và thông tin của một API operation trong Swagger UI."}, {"id": 136, "label": "Câu 136", "question": "Which HTTP method is safe (does not modify resources)?", "choices": {"A": "GET", "B": "POST", "C": "PUT", "D": "DELETE"}, "correct": "A", "correctText": "GET", "explanation": "GET là phương thức safe vì về mặt ngữ nghĩa chỉ truy xuất tài nguyên, không yêu cầu thay đổi trạng thái máy chủ; POST, PUT, DELETE dùng cho thao tác ghi."}, {"id": 137, "label": "Câu 137", "question": "Which HTTP header is used to specify the content type of a JSON response?", "choices": {"A": "Content-Language", "B": "Content-Encoding", "C": "Content-Type: application/json", "D": "Content-Length"}, "correct": "C", "correctText": "Content-Type: application/json", "explanation": "Content-Type cho biết kiểu dữ liệu của phần body.application/json thông báo nội dung được biểu diễn dưới dạng JSON."}, {"id": 138, "label": "Câu 138", "question": "Which HTTP method is idempotent?", "choices": {"A": "GET", "B": "PUT", "C": "Both GET and PUT", "D": "POST"}, "correct": "C", "correctText": "Both GET and PUT", "explanation": "GET và PUT đều idempotent: gọi lặp cùng yêu cầu có hiệu quả dự kiến như gọi một lần. GET còn là safe method, còn PUT có thể thay đổi dữ liệu."}, {"id": 139, "label": "Câu 139", "question": "What is the primary purpose of HTTP?", "choices": {"A": "To define CSS styles.", "B": "To transfer data over the internet, especially between web browsers and servers.", "C": "To manage database connections.", "D": "To handle client-side rendering exclusively."}, "correct": "B", "correctText": "To transfer data over the internet, especially between web browsers and servers.", "explanation": "HTTP là giao thức request-response giữa client và server; trình duyệt dùng nó để gửi yêu cầu và nhận status, headers và body."}, {"id": 140, "label": "Câu 140", "question": "Which annotation is used to map HTTP request bodies to method parameters in Spring Boot REST?", "choices": {"A": "@PathVariable", "B": "@RequestParam", "C": "@RequestBody", "D": "@RequestHeader"}, "correct": "C", "correctText": "@RequestBody", "explanation": "@RequestBody yêu cầu Spring chuyển JSON/XML trong request body thành tham số Java thông qua HttpMessageConverter thích hợp."}, {"id": 141, "label": "Câu 141", "question": "When should you use PUT instead of PATCH?", "choices": {"A": "When updating only part of a resource", "B": "When replacing the entire resource", "C": "When deleting a resource", "D": "When creating new resource"}, "correct": "B", "correctText": "When replacing the entire resource", "explanation": "PUT theo ngữ nghĩa HTTP dùng để tạo hoặc thay thế toàn bộ trạng thái tài nguyên tại URI; PATCH dành cho cập nhật một phần."}, {"id": 142, "label": "Câu 142", "question": "In Spring Boot REST, which annotation is used to extract path variables from the URL?", "choices": {"A": "@RequestBody", "B": "@RequestParam", "C": "@PathVariable", "D": "@RequestHeader"}, "correct": "C", "correctText": "@PathVariable", "explanation": "@PathVariable lấy giá trị trong đường dẫn như /users/{id}; @RequestParam lấy tham số query sau dấu?."}, {"id": 143, "label": "Câu 143", "question": "Which of the following is NOT a key element typically found in Spring REST documentation?", "choices": {"A": "The HTTP method (e.g., GET, POST)", "B": "The endpoint URL", "C": "The request and response payloads", "D": "The underlying database schema"}, "correct": "D", "correctText": "The underlying database schema", "explanation": "Tài liệu REST thường cần endpoint, HTTP method và cấu trúc request/response; chi tiết lược đồ database nội bộ không phải thành phần bắt buộc."}, {"id": 144, "label": "Câu 144", "question": "What is the primary role of ReactJS in a Spring Boot + React SPA architecture?", "choices": {"A": "To handle server-side logic and database interactions.", "B": "To create the user interface and handle client-side interactions.", "C": "To manage application security.", "D": "To define REST API endpoints."}, "correct": "B", "correctText": "To create the user interface and handle client-side interactions.", "explanation": "Trong SPA, React hiển thị và điều khiển UI ở browser; Spring Boot cung cấp REST API, nghiệp vụ và truy cập dữ liệu ở backend."}, {"id": 145, "label": "Câu 145", "question": "Which Axios method is typically used to update an existing resource in a RESTful API?", "choices": {"A": "axios.get()", "B": "axios.post()", "C": "axios.put()or axios.patch()", "D": "axios.delete ()"}, "correct": "C", "correctText": "axios.put()or axios.patch ()", "explanation": "axios.put() thường gửi dữ liệu thay thế/ cập nhật tài nguyên, còn axios.patch () gửi thay đổi từng phần; cả hai đều là HTTP methods hỗ trợ cập nhật."}, {"id": 146, "label": "Câu 146", "question": "Update resource?", "choices": {"A": "GET", "B": "POST", "C": "PUT", "D": "CONNECT"}, "correct": "C", "correctText": "PUT", "explanation": "PUT dùng để thay thế trạng thái của tài nguyên tại URI; nếu chỉ sửa một phần thì PATCH diễn đạt ngữ nghĩa rõ hơn."}, {"id": 147, "label": "Câu 147", "question": "Delete resource?", "choices": {"A": "REMOVE", "B": "DELETE", "C": "ERASE", "D": "PURGE"}, "correct": "B", "correctText": "DELETE", "explanation": "HTTP DELETE yêu cầu server xóa tài nguyên ở URI; gọi lại cùng yêu cầu vẫn được xem là idempotent dù mã phản hồi có thể khác."}, {"id": 148, "label": "Câu 148", "question": "Primary REST format?", "choices": {"A": "XML", "B": "CSV", "C": "JSON", "D": "TXT"}, "correct": "C", "correctText": "JSON", "explanation": "JSON là định dạng dữ liệu phổ biến cho REST API vì gọn, dễ đọc và được JavaScript hỗ trợ trực tiếp; REST không bắt buộc chỉ dùng JSON."}, {"id": 149, "label": "Câu 149", "question": "201 status means?", "choices": {"A": "OK", "B": "Created", "C": "No content", "D": "Server error"}, "correct": "B", "correctText": "Created", "explanation": "HTTP 201 Created thông báo yêu cầu đã tạo tài nguyên thành công; server thường kèm header Location trỏ đến tài nguyên mới."}, {"id": 150, "label": "Câu 150", "question": "@RestController does?", "choices": {"A": "Declares controller", "B": "RestBody", "C": "API mapping", "D": "Entity mapping"}, "correct": "A", "correctText": "Declares controller", "explanation": "@RestController đánh dấu lớp xử lý REST request và tự áp dụng @ResponseBody cho các phương thức, khiến giá trị trả về được ghi vào response body."}, {"id": 151, "label": "Câu 151", "question": "@PathVariable does?", "choices": {"A": "Extract query", "B": "Extract path", "C": "Extract body", "D": "Extract header"}, "correct": "B", "correctText": "Extract path", "explanation": "@PathVariable ánh xạ đoạn biến trong path, ví dụ /items/{id}, vào tham số phương thức controller."}, {"id": 152, "label": "Câu 152", "question": "@RequestBody does?", "choices": {"A": "Bind JSON", "B": "Bind XML", "C": "Bind header", "D": "Bind path"}, "correct": "A", "correctText": "Bind JSON", "explanation": "@RequestBody dùng message converter để đọc request body và biến JSON thành object Java tương ứng khi có bộ chuyển đổi phù hợp."}, {"id": 153, "label": "Câu 153", "question": "@GetMapping does?", "choices": {"A": "Maps POST", "B": "Maps GET", "C": "Maps DELETE", "D": "Maps PUT"}, "correct": "B", "correctText": "Maps GET", "explanation": "@GetMapping là cách viết rút gọn của @RequestMapping(met hod = RequestMet hod.GET), dùng cho endpoint đọc dữ liệu."}, {"id": 154, "label": "Câu 154", "question": "Business logic layer?", "choices": {"A": "Controller", "B": "Service", "C": "Repository", "D": "Client"}, "correct": "B", "correctText": "Service", "explanation": "Service chứa các quy tắc nghiệp vụ và phối hợp nhiều repository; controller chủ yếu tiếp nhận request và trả response."}, {"id": 155, "label": "Câu 155", "question": "Database layer?", "choices": {"A": "Service", "B": "Repository", "C": "Controller", "D": "Middleware"}, "correct": "B", "correctText": "Repository", "explanation": "Repository đóng gói thao tác truy cập database như findById, save và delete, giúp service tách khỏi chi tiết lưu trữ."}, {"id": 156, "label": "Câu 156", "question": "Purpose of @ResponseStatus?", "choices": {"A": "Add headers", "B": "Set status code", "C": "Map controller", "D": "Validate request"}, "correct": "B", "correctText": "Set status code", "explanation": "@ResponseStatus đặt status HTTP mặc định của method hoặc exception, ví dụ @ResponseStatus(Http Status.CRE ATED) cho response 201."}, {"id": 157, "label": "Câu 157", "question": "Library simplifies HTTP?", "choices": {"A": "Axios", "B": "Lodash", "C": "Redux", "D": "Vite"}, "correct": "A", "correctText": "Axios", "explanation": "Axios cung cấp API đơn giản cho HTTP request và hỗ trợ interceptor, timeout, cấu hình baseURL và chuyển đổi JSON."}, {"id": 158, "label": "Câu 158", "question": "REST stands for?", "choices": {"A": "SOAP", "B": "Representational State Transfer", "C": "Microservices", "D": "GraphQL"}, "correct": "B", "correctText": "Representational State Transfer", "explanation": "REST viết tắt của Representational State Transfer, một kiểu kiến trúc tài nguyên có các ràng buộc như stateless và uniform interface."}, {"id": 159, "label": "Câu 159", "question": "Client error?", "choices": {"A": "100", "B": "200", "C": "404", "D": "503"}, "correct": "C", "correctText": "404", "explanation": "Các mã HTTP 4xx chỉ lỗi phía client; 404 nghĩa là server không tìm thấy tài nguyên theo URI được yêu cầu."}, {"id": 160, "label": "Câu 160", "question": "Statelessness means?", "choices": {"A": "Server stores session", "B": "Each request has all info", "C": "Tracks previous", "D": "Browser stores state"}, "correct": "B", "correctText": "Each request has all info", "explanation": "Stateless đòi hỏi mỗi request mang đủ ngữ cảnh xử lý, server không cần nhớ trạng thái phiên của request trước."}, {"id": 161, "label": "Câu 161", "question": "What is the advantage of using a SPA architecture with React and Spring Boot?", "choices": {"A": "Increased server load", "B": "Improved user experience due to faster client-side rendering", "C": "Reduced application security", "D": "Increased backend complexity"}, "correct": "B", "correctText": "Improved user experience due to faster client-side rendering", "explanation": "React quản lý hiển thị và chuyển trang ngay ở trình duyệt, còn Spring Boot cung cấp API, giúp các chuyển trang sau lần tải đầu ít gián đoạn hơn."}, {"id": 162, "label": "Câu 162", "question": "What is the primary purpose of client-server communication in a React application?", "choices": {"A": "Define CSS", "B": "Fetch & send data between client and server", "C": "Manage component state", "D": "Handle server-side rendering"}, "correct": "B", "correctText": "Fetch & send data between client and server", "explanation": "Client gửi HTTP request đến API để lấy hoặc cập nhật dữ liệu, server trả status và payload; React dùng kết quả để cập nhật UI."}, {"id": 163, "label": "Câu 163", "question": "Which architectural style does REST belong to?", "choices": {"A": "Monolithic", "B": "Microservices", "C": "Representat ional State Transfer", "D": "SOA"}, "correct": "C", "correctText": "Representa tional State Transfer", "explanation": "REST là kiểu kiến trúc Representa tional State Transfer, mô tả tài nguyên và giao tiếp qua một giao diện thống nhất."}, {"id": 164, "label": "Câu 164", "question": "Benefit of separating layers in 3-layer architecture?", "choices": {"A": "Increased complexity", "B": "Reduced maintainability", "C": "Improved organization & reusability", "D": "Tighter coupling"}, "correct": "C", "correctText": "Improved organization & reusability", "explanation": "Phân tầng Controller-Service-Repository giúp tách nhiệm vụ giao tiếp HTTP, nghiệp vụ và database, khiến code dễ thử nghiệm, thay đổi và tái sử dụng."}, {"id": 165, "label": "Câu 165", "question": "Which HTTP method is idempotent?", "choices": {"A": "POST", "B": "PUT", "C": "PATCH", "D": "CONNECT"}, "correct": "B", "correctText": "PUT", "explanation": "PUT là idempotent: gửi cùng nội dung nhiều lần có trạng thái tài nguyên dự kiến như gửi một lần, dù số lượt xử lý có thể khác."}, {"id": 166, "label": "Câu 166", "question": "Which HTTP code means \"Created\"?", "choices": {"A": "200", "B": "201", "C": "404", "D": "503"}, "correct": "B", "correctText": "201", "explanation": "HTTP 201 Created báo server đã tạo xong tài nguyên mới, thường được dùng sau POST thành công."}, {"id": 167, "label": "Câu 167", "question": "Which annotation creates a REST controller?", "choices": {"A": "@Controller", "B": "@RestController", "C": "@ResponseBody", "D": "@Service"}, "correct": "B", "correctText": "@RestController", "explanation": "@RestController kết hợp @Controller và @ResponseBody, thích hợp cho API trả JSON/XML thay vì tên view."}, {"id": 168, "label": "Câu 168", "question": "Which annotation binds JSON to a Java object?", "choices": {"A": "@PathVariable", "B": "@RequestParam", "C": "@RequestBody", "D": "@ModelAttribute"}, "correct": "C", "correctText": "@RequestBody", "explanation": "Spring dùng @RequestBody cùng message converter để ánh xạ dữ liệu JSON trong body thành object Java."}, {"id": 169, "label": "Câu 169", "question": "Which annotation maps GET requests?", "choices": {"A": "@PostMapping", "B": "@GetMapping", "C": "@PutMapping", "D": "@Mapping"}, "correct": "B", "correctText": "@GetMapping", "explanation": "@GetMapping ánh xạ HTTP GET đến phương thức controller, tương đương @RequestMapping(met hod = GET)."}, {"id": 170, "label": "Câu 170", "question": "Which layer contains business logic?", "choices": {"A": "Repository", "B": "Service", "C": "Controller", "D": "Model"}, "correct": "B", "correctText": "Service", "explanation": "Service là tầng thực hiện quy tắc nghiệp vụ và điều phối repository; không nên đặt nghiệp vụ phức tạp trực tiếp trong controller."}, {"id": 171, "label": "Câu 171", "question": "Which layer handles database operations?", "choices": {"A": "Controller layer", "B": "Service layer", "C": "Repository layer", "D": "Entity layer"}, "correct": "C", "correctText": "Repository layer", "explanation": "Repository là tầng giao tiếp lưu trữ, thực hiện truy vấn và CRUD; service sử dụng repository để triển khai nghiệp vụ."}, {"id": 172, "label": "Câu 172", "question": "Which HTTP method is used to partially update a resource?", "choices": {"A": "PUT", "B": "POST", "C": "PATCH", "D": "OPTIONS"}, "correct": "C", "correctText": "PATCH", "explanation": "PATCH dùng để áp dụng một tập thay đổi lên tài nguyên, khác PUT thường biểu thị thay thế toàn bộ trạng thái tài nguyên."}, {"id": 173, "label": "Câu 173", "question": "Which HTTP status code means \"No Content\"?", "choices": {"A": "201", "B": "204", "C": "304", "D": "404"}, "correct": "B", "correctText": "204", "explanation": "HTTP 204 No Content nghĩa là request thành công nhưng response không có body, thường gặp khi DELETE thành công."}, {"id": 174, "label": "Câu 174", "question": "Which REST constraint enforces client-server independen ce?", "choices": {"A": "Statelessness", "B": "Cache", "C": "Layered system", "D": "Uniform interface"}, "correct": "A", "correctText": "Statelessness", "explanation": "Stateless không lưu ngữ cảnh hội thoại của request trước trên server, nên từng request độc lập và server có thể mở rộng linh hoạt. Ràng buộc tách vai trò client-server mới trực tiếp nói về độc lập giao diện và lưu trữ."}, {"id": 175, "label": "Câu 175", "question": "Which file contains DB credentials in Spring Boot?", "choices": {"A": "pom.xml", "B": "build.gradle", "C": "application.properties", "D": "controller.properties"}, "correct": "C", "correctText": "application.properties", "explanation": "application.properties (hoặc application.yml) thường cấu hình spring.datasource.url, username, password; nên cung cấp thông tin bí mật qua biến môi trường hoặc secret manager."}, {"id": 176, "label": "Câu 176", "question": "Which Spring annotation injects dependencies automatically?", "choices": {"A": "@Autowired", "B": "@Injectable", "C": "@Load", "D": "@Scan"}, "correct": "A", "correctText": "@Autowired", "explanation": "@Autowired yêu cầu Spring tìm bean phù hợp và tiêm vào dependency; constructor injection là cách được khuyến khích vì dễ kiểm thử."}, {"id": 177, "label": "Câu 177", "question": "Which Spring layer handles HTTP requests?", "choices": {"A": "Repository", "B": "Service", "C": "Component", "D": "Controller"}, "correct": "D", "correctText": "Controller", "explanation": "Controller nhận HTTP request, phân tích tham số và gọi service; service xử lý nghiệp vụ còn repository làm việc với database."}, {"id": 178, "label": "Câu 178", "question": "Which annotation handles exceptions globally?", "choices": {"A": "@ExceptionHandler", "B": "@ControllerAdvice", "C": "@Advice", "D": "@ErrorHandler"}, "correct": "B", "correctText": "@ControllerAdvice", "explanation": "@ControllerAdvice cho phép định nghĩa xử lý exception áp dụng cho nhiều controller; thường kết hợp @ExceptionHandler."}, {"id": 179, "label": "Câu 179", "question": "Which tool in Spring Boot auto-generates API docs?", "choices": {"A": "springdoc-openapi", "B": "lombok", "C": "swagger-core", "D": "restlet"}, "correct": "A", "correctText": "springdoc-openapi", "explanation": "springdoc-openapi đọc annotation và cấu trúc Spring MVC để sinh tài liệu OpenAPI tự động, có thể trình bày qua Swagger UI."}, {"id": 180, "label": "Câu 180", "question": "Which HTTP code indicates unauthorized?", "choices": {"A": "200", "B": "400", "C": "401", "D": "500"}, "correct": "C", "correctText": "401", "explanation": "401 Unauthorized thường nghĩa là request chưa được xác thực hợp lệ và có thể cần cung cấp credentials; 403 là đã hiểu yêu cầu nhưng không cho phép."}, {"id": 181, "label": "Câu 181", "question": "Which HTTP code indicates forbidden?", "choices": {"A": "403", "B": "401", "C": "409", "D": "500"}, "correct": "A", "correctText": "403", "explanation": "403 Forbidden nghĩa là server từ chối quyền truy cập dù đã nhận ra yêu cầu; khác 401 thường gắn với việc thiếu hoặc sai xác thực."}, {"id": 182, "label": "Câu 182", "question": "Which HTTP method is unsafe (non-idempotent)?", "choices": {"A": "GET", "B": "PUT", "C": "DELETE", "D": "POST"}, "correct": "D", "correctText": "POST", "explanation": "POST không được bảo đảm idempotent: gửi lại một request tạo đơn hàng có thể tạo thêm đơn mới, khác PUT thường thay thế cùng tài nguyên."}, {"id": 183, "label": "Câu 183", "question": "Which JSON content type is correct?", "choices": {"A": "text/json", "B": "application/json", "C": "json/applic ation", "D": "data/json"}, "correct": "B", "correctText": "application/json", "explanation": "MIME type application/json trong Content-Type cho biết body được mã hóa dạng JSON, giúp bên nhận chọn parser phù hợp."}, {"id": 184, "label": "Câu 184", "question": "Which principle requires uniform API design?", "choices": {"A": "Cacheable", "B": "Uniform interface", "C": "Stateless", "D": "Layered system"}, "correct": "B", "correctText": "Uniform interface", "explanation": "Uniform Interface là ràng buộc REST về cách tương tác thống nhất với tài nguyên qua identifier, representat ion và thông điệp tự mô tả."}, {"id": 185, "label": "Câu 185", "question": "What is the purpose of the @RequestParam annotation?", "choices": {"A": "Maps headers to method parameters", "B": "Binds form data to method parameters", "C": "Maps path variables to fields", "D": "Maps query parameters to method parameters"}, "correct": "D", "correctText": "Maps query parameters to method parameters", "explanation": "@RequestParam ánh xạ query parameter như? page=2 vào tham số Java, hỗ trợ cả giá trị mặc định và required."}, {"id": 186, "label": "Câu 186", "question": "Which Spring annotation is used to map HTTP GET requests to a method?", "choices": {"A": "@RequestGet", "B": "@Get", "C": "@HttpGet", "D": "@GetMapping"}, "correct": "D", "correctText": "@GetMapping", "explanation": "@GetMapping ánh xạ HTTP GET vào method controller, thường dùng lấy tài nguyên mà không thay đổi trạng thái."}, {"id": 187, "label": "Câu 187", "question": "Which HTTP methods are supported by Axios?", "choices": {"A": "Only GET and POST in the browser", "B": "GET, POST, PUT, DELETE, PATCH, OPTIONS, HEAD", "C": "GET, POST only", "D": "GET, POST, DELETE only"}, "correct": "B", "correctText": "GET, POST, PUT, DELETE, PATCH, OPTIONS, HEAD", "explanation": "Axios cung cấp các method cho GET, POST, PUT, PATCH, DELETE cùng các HTTP method khác như HEAD và OPTIONS."}, {"id": 188, "label": "Câu 188", "question": "How can you specify the response status code in a REST controller?", "choices": {"A": "By using HttpServlet Response", "B": "You cannot control the status code", "C": "By using @ResponseStatus annotation", "D": "By returning an int"}, "correct": "C", "correctText": "By using @ResponseStatus annotation", "explanation": "@ResponseStatus gán mã trạng thái HTTP cho method hoặc exception; ResponseEntity linh hoạt hơn nếu muốn quyết định status theo từng nhánh xử lý."}, {"id": 189, "label": "Câu 189", "question": "What is the primary purpose of a RESTful web service in Spring Boot?", "choices": {"A": "To render HTML content", "B": "To provide data through JSON or XML over HTTP", "C": "To connect to a database", "D": "To secure the application with OAuth2"}, "correct": "B", "correctText": "To provide data through JSON or XML over HTTP", "explanation": "REST service cung cấp các resource qua HTTP với những representat ion như JSON hoặc XML; frontend có thể gửi request mà không cần biết cách backend lưu dữ liệu."}, {"id": 190, "label": "Câu 190", "question": "Which of the following annotations would you use to return a specific HTTP status from a method?", "choices": {"A": "@RestStatus", "B": "@StatusCode", "C": "@ResponseStatus", "D": "@HttpStatus"}, "correct": "C", "correctText": "@ResponseStatus", "explanation": "@ResponseStatus dùng để cố định status trả về của controller method, ví dụ CREATED (201), ngay cả khi method không trả ResponseEntity."}, {"id": 191, "label": "Câu 191", "question": "Which annotation combination is used for a method that handles POST requests and accepts a request body?", "choices": {"A": "@PostMapping and @RequestParam", "B": "@PostMapping and @ResponseBody", "C": "@GetMapping and @PathVariable", "D": "@PostMapping and @RequestBody"}, "correct": "D", "correctText": "@PostMapping and @RequestBody", "explanation": "@PostMapping ánh xạ HTTP POST, còn @RequestBody yêu cầu Spring chuyển body thành đối tượng tham số Java."}, {"id": 192, "label": "Câu 192", "question": "What is the purpose of the @RequestBody annotation?", "choices": {"A": "Maps the request body to a Java object", "B": "Binds a query parameter to a method", "C": "Injects beans into controller", "D": "Validates request parameters"}, "correct": "A", "correctText": "Maps the request body to a Java object", "explanation": "@RequestBody đánh dấu tham số được tạo từ HTTP request body qua message converter, thay vì lấy từ path hoặc query string."}, {"id": 193, "label": "Câu 193", "question": "Which HTTP method is used by default when making a fetch request?", "choices": {"A": "POST", "B": "GET", "C": "DELETE", "D": "PUT"}, "correct": "B", "correctText": "GET", "explanation": "fetch(url) không truyền method sẽ mặc định dùng GET; muốn POST cần truyền thêm đối tượng options với method và body."}, {"id": 194, "label": "Câu 194", "question": "Which annotation would you use to create a REST endpoint that consumes only XML data?", "choices": {"A": "@RequestMapping(pro duces = \"application /xml\")", "B": "@GetMapping(consumes = \"application/json\")", "C": "@PostMapping(produces = \"application/json\")", "D": "@PostMapping(consumes = \"application /xml\")"}, "correct": "D", "correctText": "@PostMapping(consumes = \"application/xml\")", "explanation": "@PostMapping(consumes=\"applic ation/xml\") chỉ cho phép request có Content-Type XML cho endpoint POST; nội dung được đọc qua message converter phù hợp."}, {"id": 195, "label": "Câu 195", "question": "What is the correct annotation to define a method that handles both JSON request and response formats?", "choices": {"A": "@JsonRequest", "B": "@PostMapping with @RequestBody and @ResponseBody", "C": "@Consumes and @Produces", "D": "@RequestBody"}, "correct": "B", "correctText": "@PostMapping with @RequestBody and @ResponseBody", "explanation": "@RequestBody đọc JSON request thành object, @ResponseBody ghi object trả về vào response; @RestController cũng tự áp dụng @ResponseBody."}, {"id": 196, "label": "Câu 196", "question": "What is the effect of using @RestController instead of @Controller?", "choices": {"A": "It forces methods to return HTML views", "B": "It applies @ResponseBody to all methods by default", "C": "It disables automatic serialization", "D": "It disables exception handling"}, "correct": "B", "correctText": "It applies @ResponseBody to all methods by default", "explanation": "@RestController tương đương @Controller cộng @ResponseBody trên các method, nên dữ liệu trả về được serialize vào HTTP body thay vì tìm view."}, {"id": 197, "label": "Câu 197", "question": "How can you bind a custom header value from a request to a method parameter?", "choices": {"A": "@HeaderParam", "B": "@RequestHeader", "C": "@RequestBody", "D": "@RequestParam"}, "correct": "B", "correctText": "@RequestHeader", "explanation": "@RequestHeader ánh xạ giá trị HTTP header như X-Request-ID vào tham số controller; @RequestParam dùng cho query string còn @RequestBody dùng cho body."}, {"id": 198, "label": "Câu 198", "question": "In which file format can Swagger 3 (OpenAPI 3) specifications be written?", "choices": {"A": "XML", "B": "JSON or YAML", "C": "HTML", "D": "CSV"}, "correct": "B", "correctText": "JSON or YAML", "explanation": "OpenAPI Specification có thể được biểu diễn bằng JSON hoặc YAML; cả hai lưu cùng cấu trúc mô tả paths, parameters, requests và responses."}, {"id": 199, "label": "Câu 199", "question": "To integrate Swagger 3 with a Spring Boot 3 application, which dependency is most commonly used?", "choices": {"A": "springfox-boot-starter", "B": "springdoc-openapi-starter-webmvc-ui", "C": "swagger-core-jakarta", "D": "spring-boot-starter-docs"}, "correct": "B", "correctText": "springdoc-openapi-starter-webmvc-ui", "explanation": "Với Spring Boot 3 dùng Spring MVC, springdoc-openapi-starter-webmvc-ui tích hợp OpenAPI 3 và giao diện Swagger UI tương thích Jakarta."}, {"id": 200, "label": "Câu 200", "question": "How would you document the different possible responses for an endpoint, such as 200 OK or 404 Not Found?", "choices": {"A": "By using the @ApiResponses and @ApiResponse annotations on the controller method.", "B": "By listing them in the method's Javadoc comments.", "C": "By configuring them in the application.yml file.", "D": "By creating separate methods for each possible response code."}, "correct": "A", "correctText": "By using the @ApiResponses and @ApiResponse annotations on the controller method.", "explanation": "@ApiResponse mô tả một status code cùng nội dung phản hồi; @ApiResponses gom nhiều kết quả, ví dụ 200 và 404, cho một operation."}, {"id": 201, "label": "Câu 201", "question": "How can you group related API endpoints in Swagger 3?", "choices": {"A": "By using different @Schema annotations.", "B": "By using the tags attribute in @Tag annotations.", "C": "By using different @OpenAPIDefinition annotations.", "D": "By using different @ApiResponse annotations."}, "correct": "B", "correctText": "By using the tags attribute in @Tag annotations.", "explanation": "@Tag đặt tên nhóm cho API; các operation/ controller dùng cùng tag sẽ được gom nhóm trên Swagger UI."}, {"id": 202, "label": "Câu 202", "question": "How can you customize title/description of API in Swagger 3?", "choices": {"A": "@Operation", "B": "@Schema", "C": "@OpenAPIDefinition", "D": "@ApiResponse"}, "correct": "C", "correctText": "@OpenAPIDefinition", "explanation": "@OpenAPIDefinition khai báo metadata chung cho tài liệu OpenAPI như Info.title, version và description."}, {"id": 203, "label": "Câu 203", "question": "What is Swagger used for?", "choices": {"A": "Logging", "B": "API documentation", "C": "SQL queries", "D": "Testing UI"}, "correct": "B", "correctText": "API documentation", "explanation": "Swagger/OpenAPI mô tả đường dẫn API, tham số, body và kiểu response; Swagger UI tạo giao diện tài liệu có thể thử API."}, {"id": 204, "label": "Câu 204", "question": "Swagger UI is accessed by default at:", "choices": {"A": "/docs", "B": "/documentation", "C": "/swagger-ui/index.html", "D": "/openapi"}, "correct": "C", "correctText": "/swagger-ui/index.html", "explanation": "Với cấu hình Springdoc thông dụng, Swagger UI mở tại /swagger-ui/index.html; đường dẫn có thể thay đổi bằng cấu hình ứng dụng."}, {"id": 205, "label": "Câu 205", "question": "Swagger's @Operation is used to:", "choices": {"A": "Define REST controller", "B": "Document API method", "C": "Map exception", "D": "Generate model schema"}, "correct": "B", "correctText": "Document API method", "explanation": "@Operation mô tả endpoint OpenAPI gồm summary, description và các thông tin để Swagger UI hiển thị."}, {"id": 206, "label": "Câu 206", "question": "What is API documentation used for?", "choices": {"A": "Styling UI", "B": "Helping developers use the API", "C": "Running SQL scripts", "D": "Caching assets"}, "correct": "B", "correctText": "Helping developers use the API", "explanation": "API documentation cho biết endpoint, method, tham số, xác thực và mẫu request/response để các lập trình viên tích hợp đúng."}, {"id": 207, "label": "Câu 207", "question": "Which OpenAPI annotation groups API operations?", "choices": {"A": "@Operation", "B": "@Tag", "C": "@Schema", "D": "@Info"}, "correct": "B", "correctText": "@Tag", "explanation": "@Tag gán nhóm cho các API operation trong OpenAPI; nhiều endpoint cùng tag sẽ xuất hiện trong cùng nhóm trên Swagger UI."}, {"id": 208, "label": "Câu 208", "question": "Which OpenAPI annotation documents an endpoint?", "choices": {"A": "@DocumentAPI", "B": "@Endpoint", "C": "@Operation", "D": "@Info"}, "correct": "C", "correctText": "@Operation", "explanation": "@Operation cung cấp metadata cho một endpoint như summary và description, khác @Schema mô tả model dữ liệu."}, {"id": 209, "label": "Câu 209", "question": "Which OpenAPI annotation describes a model/class?", "choices": {"A": "@Schema", "B": "@Model", "C": "@Data", "D": "@Class"}, "correct": "A", "correctText": "@Schema", "explanation": "@Schema mô tả kiểu dữ liệu, field, ví dụ hoặc ràng buộc của model được đưa vào OpenAPI components.schemas."}, {"id": 210, "label": "Câu 210", "question": "Which file defines API versioning?", "choices": {"A": "version.xml", "B": "application.properties", "C": "openapi-config.java", "D": "routes.js"}, "correct": "B", "correctText": "application.properties", "explanation": "application.properties có thể chứa cấu hình version API do ứng dụng tự thiết kế, nhưng Spring Boot không mặc định dùng một tệp riêng để quy định phiên bản; version thường biểu diễn trong URL hoặc header."}, {"id": 211, "label": "Câu 211", "question": "Which annotation is used to describe the request body content in an OpenAPI operation?", "choices": {"A": "@ApiBody", "B": "@RequestContent", "C": "@RequestBody (from swagger package)", "D": "@RequestDoc"}, "correct": "C", "correctText": "@RequestBody (from swagger package)", "explanation": "@RequestBody thuộc gói annotation OpenAPI mô tả schema, media type và ví dụ request body trong tài liệu; không nhầm với @RequestBody của Spring dùng để bind dữ liệu."}, {"id": 212, "label": "Câu 212", "question": "What Spring configuration property changes the default OpenAPI endpoint?", "choices": {"A": "swagger.api.url", "B": "openapi.swagger.path", "C": "spring.openapi.path", "D": "springdoc.api-docs.path"}, "correct": "D", "correctText": "springdoc.api-docs.path", "explanation": "springdoc.api-docs.path đổi đường dẫn phục vụ tài liệu OpenAPI JSON, chẳng hạn từ /v3/api-docs sang đường dẫn tùy chỉnh."}, {"id": 213, "label": "Câu 213", "question": "How do you group APIs in Swagger UI using Springdoc OpenAPI?", "choices": {"A": "Using @Group", "B": "Using @Tag(name = 'GroupName')", "C": "Using @SwaggerGroup", "D": "Using application.yaml grouping"}, "correct": "B", "correctText": "Using @Tag(name = 'GroupName')", "explanation": "@Tag(name =\"...\") gắn tên nhóm cho controller hoặc operation trong tài liệu OpenAPI; Swagger UI gom các endpoint theo tag."}, {"id": 214, "label": "Câu 214", "question": "Which dependency is commonly used in Spring Boot to integrate OpenAPI 3?", "choices": {"A": "springdoc-openapi-ui", "B": "spring-boot-devtools", "C": "springfox-swagger2", "D": "spring-boot-starter-jdbc"}, "correct": "A", "correctText": "springdoc-openapi-ui", "explanation": "springdoc-openapi-ui là artifact tích hợp Swagger UI từng dùng với các đời Spring Boot cũ; với Spring Boot 3 nên dùng starter tương ứng như springdoc-openapi-starter-webmvc-ui."}, {"id": 215, "label": "Câu 215", "question": "How can you hide an endpoint from OpenAPI documentation?", "choices": {"A": "Disable the controller", "B": "Use @IgnoreMapping", "C": "Add @Hidden annotation", "D": "Rename the method"}, "correct": "C", "correctText": "Add @Hidden annotation", "explanation": "@Hidden của springdoc/swagger-core loại một controller hoặc endpoint khỏi tài liệu OpenAPI, nhưng không tự vô hiệu hóa API thật."}, {"id": 216, "label": "Câu 216", "question": "What is the purpose of the JWT header?", "choices": {"A": "To store user data.", "B": "To store the signing algorithm and token type.", "C": "To store the signature.", "D": "To store the expiration time."}, "correct": "B", "correctText": "To store the signing algorithm and token type.", "explanation": "JWT gồm Header, Payload và Signature. Header khai báo loại token và thuật toán ký như HS256; thông tin người dùng thường nằm trong Payload."}, {"id": 217, "label": "Câu 217", "question": "How are credentials transmitted in HTTP Basic authentication?", "choices": {"A": "Encrypted using a server-side public key.", "B": "Sent in plain text in the request body.", "C": "Base64-encoded and sent in the Authorization header.", "D": "Hashed using a nonce and a server-side secret."}, "correct": "C", "correctText": "Base64-encoded and sent in the Authorization header.", "explanation": "HTTP Basic ghép username rồi mã hóa Base64, gửi bằng header Authorization với tiền tố Basic.Base64 không phải mã hóa bảo mật nên cần HTTPS."}, {"id": 218, "label": "Câu 218", "question": "Where is the session ID typically stored in Session-Based Security?", "choices": {"A": "In the request header.", "B": "In the request body.", "C": "In a cookie or URL.", "D": "In the server's database."}, "correct": "C", "correctText": "In a cookie or URL.", "explanation": "Máy chủ giữ dữ liệu session, còn trình duyệt thường giữ session ID trong cookie JSESSIONID. ID cũng có thể được truyền trên URL nhưng kém an toàn hơn."}, {"id": 219, "label": "Câu 219", "question": "Which authentication method sends credentials with every request in RESTful APIs?", "choices": {"A": "Session-based authentication", "B": "Token-based authentication (JWT)", "C": "OAuth 2.0", "D": "Basic Authentication"}, "correct": "D", "correctText": "Basic Authentication", "explanation": "Basic Authentication gửi cặp username được mã hóa Base64 trong header Authorization ở mỗi request.Session ID và JWT sử dụng thông tin định danh khác."}, {"id": 220, "label": "Câu 220", "question": "What is the purpose of Spring Boot Security?", "choices": {"A": "To manage database connections.", "B": "To provide authentication and authorization functionality.", "C": "To handle HTTP requests and responses.", "D": "To manage application configuration."}, "correct": "B", "correctText": "To provide authentication and authorization functionality.", "explanation": "Spring Security kiểm tra danh tính (authentication) và quyền truy cập (authorization), qua filter chain trước khi request vào controller."}, {"id": 221, "label": "Câu 221", "question": "What is the second step in implementing JWT in Spring REST?", "choices": {"A": "Create a JWT utility class for generating and validating tokens.", "B": "Configure Spring Security.", "C": "Implement user authentication.", "D": "Create a database schema."}, "correct": "A", "correctText": "Create a JWT utility class for generating and validating tokens.", "explanation": "Một tiện ích JWT có chức năng tạo token đã ký, xác minh chữ ký và thời hạn; sau đó có thể nối nó vào luồng đăng nhập và filter xác thực."}, {"id": 222, "label": "Câu 222", "question": "What is JWT mainly used for?", "choices": {"A": "Data storage", "B": "Authentication", "C": "CSS styling", "D": "Routing"}, "correct": "B", "correctText": "Authentication", "explanation": "JWT là token mang claims có chữ ký dùng để chứng minh kết quả xác thực trong các request; vẫn phải kiểm tra chữ ký và thời hạn."}, {"id": 223, "label": "Câu 223", "question": "Which security method is most secure?", "choices": {"A": "HTTP Basic", "B": "Session ID", "C": "JWT over HTTPS", "D": "No authentication"}, "correct": "C", "correctText": "JWT over HTTPS", "explanation": "HTTPS mã hóa đường truyền và bảo vệ token JWT khỏi bị đọc trộm khi truyền; độ an toàn thực tế còn phụ thuộc cách lưu token, xác minh và quản lý khóa."}, {"id": 224, "label": "Câu 224", "question": "Which authentication uses cookies?", "choices": {"A": "Digest Auth", "B": "JWT", "C": "OAuth2", "D": "Session-based auth"}, "correct": "D", "correctText": "Session-based auth", "explanation": "Session-based authentication thường gửi session ID qua cookie sau khi đăng nhập; máy chủ dùng ID đó để tra trạng thái phiên."}, {"id": 225, "label": "Câu 225", "question": "Which Spring annotation defines security configuration?", "choices": {"A": "@Bean", "B": "@Configuration", "C": "@SecurityScheme", "D": "@EnableWebSecurity"}, "correct": "D", "correctText": "@EnableWebSecurity", "explanation": "@EnableWebSecurity kích hoạt tích hợp cấu hình bảo mật web của Spring Security trong cấu hình phù hợp; các quy tắc truy cập thường định nghĩa qua SecurityFilterChain."}, {"id": 226, "label": "Câu 226", "question": "OAuth2 allows:", "choices": {"A": "Servers to share HTML", "B": "Apps to access user resources safely", "C": "Auto CSS injection", "D": "SQL validation"}, "correct": "B", "correctText": "Apps to access user resources safely", "explanation": "OAuth 2.0 cho ứng dụng nhận quyền truy cập giới hạn qua access token mà không cần biết mật khẩu người dùng tại mỗi resource server."}, {"id": 227, "label": "Câu 227", "question": "Which method returns a JWT once a user logs in?", "choices": {"A": "authenticate()", "B": "validate()", "C": "register()", "D": "authorize()"}, "correct": "A", "correctText": "authenticate()", "explanation": "Trong nhiều thiết kế, authenticate() kiểm tra thông tin đăng nhập và sau đó tạo JWT cho người dùng. Đây là tên method do ứng dụng tự định nghĩa, không phải API cố định của Spring."}, {"id": 228, "label": "Câu 228", "question": "JWT improves scalability because it is:", "choices": {"A": "Encrypted", "B": "Stateless", "C": "Server-stored", "D": "Limited"}, "correct": "B", "correctText": "Stateless", "explanation": "JWT có thể được xác minh bằng chữ ký mà không tra session phía server ở mọi request, thuận lợi phân phối request giữa nhiều máy chủ."}, {"id": 229, "label": "Câu 229", "question": "What should you ALWAYS use with Basic Auth?", "choices": {"A": "HTTP", "B": "HTTPS", "C": "Plain text", "D": "Cookies"}, "correct": "B", "correctText": "HTTPS", "explanation": "Basic Auth chỉ mã hóa Base64 nên ai thấy header đều có thể giải mã username và password; HTTPS bảo vệ chúng trên đường truyền."}, {"id": 230, "label": "Câu 230", "question": "Digest authentication improves security using:", "choices": {"A": "Base64 encoding", "B": "Nonce values", "C": "Cookies", "D": "SQL locks"}, "correct": "B", "correctText": "Nonce values", "explanation": "HTTP Digest dùng nonce và giá trị băm trong cơ chế thử thách-đáp ứng, tránh gửi mật khẩu nguyên dạng như Basic; hiện nay vẫn nên dùng HTTPS."}, {"id": 231, "label": "Câu 231", "question": "Certificate-based authentication uses:", "choices": {"A": "JSON tokens", "B": "SSL/TLS certificates", "C": "Cookies", "D": "QR codes"}, "correct": "B", "correctText": "SSL/TLS certificates", "explanation": "Certificate-based authentication dùng chứng chỉ X.509 trong TLS để xác minh danh tính máy chủ hoặc client, dựa trên chuỗi tin cậy và khóa công khai."}, {"id": 232, "label": "Câu 232", "question": "OAuth2 uses:", "choices": {"A": "User passwords", "B": "Tokens", "C": "SQL queries", "D": "Cookies"}, "correct": "B", "correctText": "Tokens", "explanation": "OAuth 2.0 cấp access token đại diện phạm vi quyền được cho phép; resource server kiểm tra token trước khi cấp tài nguyên."}, {"id": 233, "label": "Câu 233", "question": "Which OAuth component verifies identity?", "choices": {"A": "Resource owner", "B": "Resource server", "C": "Authorization server", "D": "Client"}, "correct": "C", "correctText": "Authorization server", "explanation": "Authorization server thực hiện luồng cấp token và có thể xác thực người dùng; trong OpenID Connect, identity còn được mô tả rõ bằng ID token."}, {"id": 234, "label": "Câu 234", "question": "Which part of JWT contains claims?", "choices": {"A": "Header", "B": "Payload", "C": "Hash", "D": "Signature"}, "correct": "B", "correctText": "Payload", "explanation": "Payload của JWT chứa claims như sub, exp, iss và role; payload chỉ được Base64URL-encode, không tự được mã hóa bí mật."}, {"id": 235, "label": "Câu 235", "question": "Which part of JWT ensures integrity?", "choices": {"A": "Payload", "B": "Signature", "C": "URL", "D": "Header"}, "correct": "B", "correctText": "Signature", "explanation": "Signature là chữ ký tính từ Header, Payload và khóa; kiểm tra chữ ký phát hiện nội dung token bị thay đổi."}, {"id": 236, "label": "Câu 236", "question": "JWT is vulnerable if:", "choices": {"A": "Secret key is weak", "B": "HTTPS is used", "C": "Token is short", "D": "User logs out"}, "correct": "A", "correctText": "Secret key is weak", "explanation": "Khóa ký JWT yếu có thể bị đoán hoặc brute-force, từ đó kẻ tấn công tự tạo token có chữ ký hợp lệ; cần dùng khóa mạnh và thuật toán an toàn."}, {"id": 237, "label": "Câu 237", "question": "What is the main weakness of JWT?", "choices": {"A": "Hard to generate", "B": "Hard to revoke early", "C": "Requires SQL", "D": "Breaks routing"}, "correct": "B", "correctText": "Hard to revoke early", "explanation": "JWT tự chứa thông tin và có thể tiếp tục hợp lệ đến khi exp, nên thu hồi sớm khó hơn session server-side; có thể dùng denylist hoặc access token ngắn hạn."}, {"id": 238, "label": "Câu 238", "question": "Which Spring term identifies the authenticated user?", "choices": {"A": "Principal", "B": "Subject", "C": "Authority", "D": "Claim"}, "correct": "A", "correctText": "Principal", "explanation": "Principal đại diện danh tính của chủ thể đã xác thực trong security context; có thể lấy từ Authentication.getPrincipal()."}, {"id": 239, "label": "Câu 239", "question": "GrantedAuthority represents:", "choices": {"A": "Password", "B": "Permission/role", "C": "Username", "D": "Token"}, "correct": "B", "correctText": "Permission/role", "explanation": "GrantedAuthority biểu diễn một quyền hoặc role được cấp cho user, thường ở dạng chuỗi như ROLE_ADMIN để kiểm tra authorization."}, {"id": 240, "label": "Câu 240", "question": "Which annotation restricts access by role?", "choices": {"A": "@Block", "B": "@RolesAllowed", "C": "@Allow", "D": "@Access"}, "correct": "B", "correctText": "@RolesAllowed", "explanation": "@RolesAllowed cho phép giới hạn việc gọi method theo role được khai báo khi bật method security tương ứng."}, {"id": 241, "label": "Câu 241", "question": "Which class handles JWT creation/validation?", "choices": {"A": "JwtUtils", "B": "JwtEngine", "C": "TokenService", "D": "SecurityBuilder"}, "correct": "A", "correctText": "JwtUtils", "explanation": "JwtUtils thường là lớp tiện ích do dự án tự xây dựng để tạo và kiểm tra token JWT; không phải class bắt buộc có sẵn của Spring."}, {"id": 242, "label": "Câu 242", "question": "What security issue is more pronounced in SPAs due to heavy client-side processing?", "choices": {"A": "Server misconfiguration", "B": "SSL certificate expiration", "C": "Database injection", "D": "Cross-Site Scripting (XSS)"}, "correct": "D", "correctText": "Cross-Site Scripting (XSS)", "explanation": "XSS cho phép mã JavaScript độc chạy trong trang, có thể đọc dữ liệu nhạy cảm hoặc thực hiện thao tác thay người dùng; cần escape output, CSP và quản lý token an toàn."}, {"id": 243, "label": "Câu 243", "question": "What is the purpose of HttpSession.invalidate() in session-based security?", "choices": {"A": "Remove the current session and all its attributes", "B": "Restart the session with the same session ID", "C": "Encrypt the session data", "D": "Extend session timeout"}, "correct": "A", "correctText": "Remove the current session and all its attributes", "explanation": "HttpSession.invalidate() hủy session hiện tại và vô hiệu hóa các thuộc tính đã lưu; request dùng lại session ID cũ không còn truy cập phiên đó."}, {"id": 244, "label": "Câu 244", "question": "What happens if a client sends a request without an Authorization header and the server requires Basic Auth?", "choices": {"A": "Server responds with 200 OK and empty body", "B": "Server responds with 401 Unauthorized and WWW-Authenticate header", "C": "Server closes the connection immediately", "D": "Server automatically redirects to login page"}, "correct": "B", "correctText": "Server responds with 401 Unauthorized and WWW-Authenticate header", "explanation": "Với Basic Auth, server gửi 401 kèm WWW-Authenticate: Basic để yêu cầu credentials; trình duyệt có thể hiện hộp thoại đăng nhập."}, {"id": 245, "label": "Câu 245", "question": "How can a server prompt the browser to show a login dialog for Basic Auth?", "choices": {"A": "By including WWW-Authenticate: Basic realm='RealmName' in a 401 response", "B": "By sending a Set-Cookie header with a token", "C": "By returning 403 with Login-Required: true", "D": "By using JavaScript redirect"}, "correct": "A", "correctText": "By including WWW-Authenticate: Basic realm='RealmName' in a 401 response", "explanation": "Header WWW-Authenticate: Basic realm=\"...\" trong response 401 mô tả cơ chế xác thực và vùng bảo vệ, khiến browser có thể hỏi thông tin đăng nhập."}, {"id": 246, "label": "Câu 246", "question": "In Basic Authentication, what does the format of the Authorization header look like?", "choices": {"A": "Authorization: Bearer (token)", "B": "Authorization: Basic (base64(username))", "C": "Authorization: Token username", "D": "Auth: Basic (JWT)"}, "correct": "B", "correctText": "Authorization: Basic (base64(username))", "explanation": "Basic Auth có header Authorization: Basic <Base64(username)>; Base64 chỉ là encoding chứ không bảo mật thông tin như HTTPS."}, {"id": 247, "label": "Câu 247", "question": "Which HTTP header is commonly used to transmit the session ID?", "choices": {"A": "Authorization", "B": "Cookie", "C": "X-Session-Token", "D": "Set-Header"}, "correct": "B", "correctText": "Cookie", "explanation": "Header Cookie của request mang session cookie như JSESSIONID từ browser đến server; Set-Cookie là header server dùng để thiết lập cookie."}, {"id": 248, "label": "Câu 248", "question": "Which of the following is false about Basic Authentication?", "choices": {"A": "It does not require session on server", "B": "It is stateless", "C": "It can be used with REST APIs", "D": "It is considered more secure than OAuth2"}, "correct": "D", "correctText": "It is considered more secure than OAuth2", "explanation": "Basic Auth gửi credentials lặp lại và phụ thuộc HTTPS để bảo vệ trên đường truyền; OAuth 2.0 cho phép cấp token có scope và thời hạn nên không thể nói Basic an toàn hơn."}, {"id": 249, "label": "Câu 249", "question": "What object is used to specify the page number and page size in Spring Data JPA?", "choices": {"A": "Sort", "B": "Pageable", "C": "Slice", "D": "List"}, "correct": "B", "correctText": "Pageable", "explanation": "Pageable chứa số trang và kích thước trang; Spring Data dùng nó để phân trang truy vấn. Sort chỉ quy định thứ tự sắp xếp."}, {"id": 250, "label": "Câu 250", "question": "What annotation is used to inject a Spring Data JPA repository into a service or controller?", "choices": {"A": "@RequestMapping", "B": "@Autowired", "C": "@RestController", "D": "@Entity"}, "correct": "B", "correctText": "@Autowired", "explanation": "@Autowired yêu cầu Spring tiêm bean phụ thuộc vào lớp đang dùng, gồm cả repository. Constructor injection cũng thực hiện được mà không cần annotation nếu chỉ có một constructor."}, {"id": 251, "label": "Câu 251", "question": "When should you use the Slice interface in Spring Data JPA?", "choices": {"A": "When you need the total number of elements and total pages.", "B": "When you want to avoid counting all elements and improve performance.", "C": "When you need to sort the results with detailed page information.", "D": "When you only need the data and a \"previous\" indicator."}, "correct": "B", "correctText": "When you want to avoid counting all elements and improve performance.", "explanation": "Slice chỉ cho biết có trang tiếp theo hay không, không cần truy vấn COUNT để biết tổng số phần tử. Page thường cần tổng số bản ghi và tổng số trang."}, {"id": 252, "label": "Câu 252", "question": "What does the <mapping resource=\"User.hbm.xml\"> tag in hibernate.cfg.xml specify?", "choices": {"A": "The database connection URL.", "B": "The database dialect.", "C": "The location of a Hibernate mapping file that defines how a Java class is mapped to a database table.", "D": "The location of the Hibernate configuration file."}, "correct": "C", "correctText": "The location of a Hibernate mapping file that defines how a Java class is mapped to a database table.", "explanation": "Thẻ mapping resource trỏ tới tệp XML ánh xạ Hibernate, chẳng hạn User.hbm.xml, nơi mô tả liên hệ giữa lớp Java với bảng và cột."}, {"id": 253, "label": "Câu 253", "question": "What does the \"Transient\" state of an object in Hibernate indicate?", "choices": {"A": "The object is associated with a Session and has a corresponding database record.", "B": "The object is not associated with any Session and does not have a database record.", "C": "The object was previously associated with a Session but is now detached.", "D": "The object is cached in the second-level cache."}, "correct": "B", "correctText": "The object is not associated with any Session and does not have a database record.", "explanation": "Transient là entity vừa tạo nhưng chưa được quản lý bởi Hibernate Session và chưa có bản ghi tương ứng. Khi persist, nó chuyển sang trạng thái managed."}, {"id": 254, "label": "Câu 254", "question": "In JPA, which annotation defines a many-to-many relationship?", "choices": {"A": "@OneToOne", "B": "@OneToMany", "C": "@ManyToMany", "D": "@JoinColumn"}, "correct": "C", "correctText": "@ManyToMany", "explanation": "@ManyToMany mô tả quan hệ nhiều-nhiều, thường thông qua bảng trung gian chứa khóa ngoại đến hai entity."}, {"id": 255, "label": "Câu 255", "question": "Which Hibernate Cache property enables the second-level cache?", "choices": {"A": "hibernate.cache.use_second_level_cache", "B": "hibernate.cache.provider_class", "C": "hibernate.cache.region.factory_class", "D": "hibernate.cache.use_query_cache"}, "correct": "A", "correctText": "hibernate.cache.use_second_level_cache", "explanation": "hibernate.cache.use_second_level_cache bật bộ đệm cấp 2 dùng chung giữa các Session; còn bộ đệm cấp 1 luôn gắn với một Session."}, {"id": 256, "label": "Câu 256", "question": "What is the purpose of the @GeneratedValue annotation?", "choices": {"A": "To define a column name.", "B": "To specify the strategy for generating primary key values.", "C": "To create a new table.", "D": "To define a new entity."}, "correct": "B", "correctText": "To specify the strategy for generating primary key values.", "explanation": "@GeneratedValue cấu hình chiến lược sinh khóa chính như IDENTITY, SEQUENCE hoặc AUTO, thường đi cùng trường được đánh dấu @Id."}, {"id": 257, "label": "Câu 257", "question": "Which method is used to create a Sort object for ascending order?", "choices": {"A": "Sort.descending()", "B": "Sort.ascending()", "C": "Sort.unsorted()", "D": "Sort.by()"}, "correct": "D", "correctText": "Sort.by()", "explanation": "Sort.by(\"name\") tạo đối tượng Sort sắp xếp tăng dần theo mặc định; cũng có thể dùng Sort.by(Sort.Direction.ASC, \"name\")."}, {"id": 258, "label": "Câu 258", "question": "What is the primary reason for connecting a RESTful web service to JPA?", "choices": {"A": "To increase API complexity.", "B": "To simplify data persistence and retrieval.", "C": "To hide database interactions.", "D": "To reduce API functionality."}, "correct": "B", "correctText": "To simplify data persistence and retrieval.", "explanation": "JPA ánh xạ entity Java thành dữ liệu quan hệ và cung cấp CRUD, giúp REST controller/ service không phải tự viết SQL cho mọi thao tác."}, {"id": 259, "label": "Câu 259", "question": "How does JPA help in managing database interactions?", "choices": {"A": "By requiring manual SQL queries for every operation.", "B": "By providing an object-relational mapping (ORM) layer.", "C": "By hiding all data from the application.", "D": "By increasing the number of database connections."}, "correct": "B", "correctText": "By providing an object-relational mapping (ORM) layer.", "explanation": "JPA dùng ORM để ánh xạ lớp, thuộc tính và quan hệ Java sang bảng, cột và khóa ngoại trong cơ sở dữ liệu quan hệ."}, {"id": 260, "label": "Câu 260", "question": "Which statement about optimistic locking in JPA is true?", "choices": {"A": "It prevents concurrent data conflicts", "B": "It improves UI rendering", "C": "It replaces caching", "D": "It manages database indexes"}, "correct": "A", "correctText": "It prevents concurrent data conflicts", "explanation": "Optimistic locking thường dùng trường @Version; khi bản ghi bị người khác sửa trước, phép cập nhật phát hiện version lệch và tránh ghi đè lẫn nhau."}, {"id": 261, "label": "Câu 261", "question": "Which key feature of Hibernate provides automatic table creation and schema generation?", "choices": {"A": "Caching.", "B": "hbm2ddl (DDL auto feature)", "C": "Automatic dirty checking.", "D": "Transaction management."}, "correct": "B", "correctText": "hbm2ddl (DDL auto feature)", "explanation": "hibernate.hbm2ddl.auto có các chế độ như validate, update, create để kiểm tra hoặc sinh schema từ mapping entity; cần thận trọng với create trong môi trường thật."}, {"id": 262, "label": "Câu 262", "question": "Which interface in Hibernate is used to manage database transactions?", "choices": {"A": "Session.", "B": "Transaction.", "C": "SessionFactory.", "D": "Configuration."}, "correct": "B", "correctText": "Transaction.", "explanation": "Hibernate Transaction cung cấp begin/commit/rollback để xác định một đơn vị công việc nhất quán; Session chủ yếu quản lý entity và thao tác truy cập dữ liệu."}, {"id": 263, "label": "Câu 263", "question": "Given a Book entity, which derived query method correctly finds all books published after a certain date and sorts them by title?", "choices": {"A": "List<Book> findByPublishedDateAfterOrderByTitleAsc(LocalDate date);", "B": "List<Book> findAllBooksAfterDateAndSortByTitle(LocalDate date);", "C": "List<Book> findByPublishedDate(LocalDate date, Sort sort);", "D": "List<Book> queryAfterPublishedDateSortedByTitle(LocalDate date);"}, "correct": "A", "correctText": "List<Book> findByPublishedDateAfterOrderByTitleAsc(LocalDate date);", "explanation": "Spring Data phân tích tên hàm: PublishedDateAfter tạo điều kiện ngày lớn hơn mốc, còn OrderByTitleAsc sắp xếp tăng dần theo title."}, {"id": 264, "label": "Câu 264", "question": "What is the purpose of the <property name=\"hibernate.dialect\"> tag in hibernate.cfg.xml?", "choices": {"A": "To specify the database driver class.", "B": "To define the SQL dialect used by Hibernate for the specific database.", "C": "To map Java classes to database tables.", "D": "To configure the session factory"}, "correct": "B", "correctText": "To define the SQL dialect used by Hibernate for the specific database.", "explanation": "Hibernate dùng SQL dialect để sinh cú pháp SQL phù hợp từng hệ quản trị như MySQL hoặc PostgreSQL, vì các hệ này có khác biệt về kiểu dữ liệu và câu lệnh."}, {"id": 265, "label": "Câu 265", "question": "Which Spring Data JPA interface performs CRUD operations?", "choices": {"A": "CrudRepository", "B": "ServiceRepository", "C": "ControllerRepository", "D": "EntityRepository"}, "correct": "A", "correctText": "CrudRepository", "explanation": "CrudRepository cung cấp các hàm CRUD cơ bản như save, findById, findAll và deleteById; JpaRepository mở rộng thêm các tiện ích JPA."}, {"id": 266, "label": "Câu 266", "question": "Purpose of hibernate.dialect property?", "choices": {"A": "Specify DB driver", "B": "Define SQL dialect", "C": "Map Java classes", "D": "Configure session factory"}, "correct": "B", "correctText": "Define SQL dialect", "explanation": "SQL dialect cho Hibernate biết dạng cú pháp và tính năng SQL của database cụ thể để sinh câu lệnh đúng hệ quản trị."}, {"id": 267, "label": "Câu 267", "question": "What is the role of Hibernate Session object?", "choices": {"A": "Manage transactions", "B": "Interact with DB & perform CRUD", "C": "Store configs", "D": "Cache queries"}, "correct": "B", "correctText": "Interact with DB & perform CRUD", "explanation": "Hibernate Session đại diện một đơn vị làm việc với persistence context, hỗ trợ truy vấn và lưu entity cũng như theo dõi thay đổi."}, {"id": 268, "label": "Câu 268", "question": "What is Hibernate used for?", "choices": {"A": "Create HTML", "B": "Map Java objects to DB tables", "C": "Build REST APIs", "D": "Create CSS"}, "correct": "B", "correctText": "Map Java objects to DB tables", "explanation": "Hibernate là công cụ ORM ánh xạ các lớp Java sang bảng quan hệ, tự chuyển nhiều thao tác object thành SQL."}, {"id": 269, "label": "Câu 269", "question": "What file configures Hibernate?", "choices": {"A": "hibernate.xml", "B": "config.properties", "C": "hibernate.cfg.xml", "D": "database.xml"}, "correct": "C", "correctText": "hibernate.cfg.xml", "explanation": "hibernate.cfg.xml thường chứa cấu hình kết nối, SQL dialect và mapping cần thiết cho Hibernate SessionFactory."}, {"id": 270, "label": "Câu 270", "question": "Which annotation maps a class to a DB table?", "choices": {"A": "@Entity", "B": "@Table", "C": "@Model", "D": "@Database"}, "correct": "A", "correctText": "@Entity", "explanation": "@Entity khai báo lớp Java là entity được JPA quản lý; mặc định tên bảng thường dựa trên tên entity, có thể chỉnh bằng @Table."}, {"id": 271, "label": "Câu 271", "question": "Which fetching strategy loads immediately?", "choices": {"A": "Lazy", "B": "Eager", "C": "Manual", "D": "Linked"}, "correct": "B", "correctText": "Eager", "explanation": "FetchType.EAGER yêu cầu dữ liệu quan hệ được lấy ngay cùng quá trình load entity, có thể tăng số truy vấn hoặc lượng dữ liệu tải."}, {"id": 272, "label": "Câu 272", "question": "Which JPA repository provides CRUD?", "choices": {"A": "JpaRepoBase", "B": "CrudRepository", "C": "DataRepo", "D": "BaseRepository"}, "correct": "B", "correctText": "CrudRepository", "explanation": "CrudRepository định nghĩa các thao tác chuẩn như save, findById và deleteById; JpaRepository mở rộng khả năng cho JPA."}, {"id": 273, "label": "Câu 273", "question": "Which annotation maps an entity to a specific database table?", "choices": {"A": "@Id", "B": "@Table", "C": "@Column", "D": "@Entity"}, "correct": "B", "correctText": "@Table", "explanation": "@Table(name=\"...\") đặt tên bảng cho entity JPA; @Entity là annotation khiến lớp được quản lý như một entity."}, {"id": 274, "label": "Câu 274", "question": "Which JPA annotation maps a field to a column?", "choices": {"A": "@Id", "B": "@Column", "C": "@Primary", "D": "@Key"}, "correct": "B", "correctText": "@Column", "explanation": "@Column đặt tên cột, nullable, unique và các thuộc tính ánh xạ của field entity; nếu bỏ qua, JPA thường dùng quy ước mặc định."}, {"id": 275, "label": "Câu 275", "question": "Which Hibernate feature automatically maps classes to tables?", "choices": {"A": "HQL", "B": "ORM", "C": "SQLBuilder", "D": "JDBC"}, "correct": "B", "correctText": "ORM", "explanation": "ORM tự ánh xạ lớp/field Java thành bảng/cột, giúp lập trình viên thao tác entity thay vì tự viết toàn bộ SQL."}, {"id": 276, "label": "Câu 276", "question": "Hibernate HQL is used for:", "choices": {"A": "SQL queries only", "B": "Object-based querying", "C": "CSS styling", "D": "API routing"}, "correct": "B", "correctText": "Object-based querying", "explanation": "Hibernate Query Language (HQL) viết truy vấn theo tên entity và thuộc tính Java; Hibernate dịch HQL thành SQL cho database."}, {"id": 277, "label": "Câu 277", "question": "Which Hibernate cache improves performance?", "choices": {"A": "First-level cache", "B": "No cache", "C": "XML cache", "D": "SQL cache"}, "correct": "A", "correctText": "First-level cache", "explanation": "First-level cache thuộc riêng từng Hibernate Session, tránh truy vấn database lặp lại khi lấy cùng entity trong cùng persistence context."}, {"id": 278, "label": "Câu 278", "question": "Which annotation creates a Spring Bean?", "choices": {"A": "@SpringBootApplication", "B": "@Bean", "C": "@Autowired", "D": "@Configuration"}, "correct": "B", "correctText": "@Bean", "explanation": "@Bean trên method cấu hình báo Spring lấy giá trị trả về của method làm bean trong Application Context."}, {"id": 279, "label": "Câu 279", "question": "Which Spring Boot dependency enables JPA?", "choices": {"A": "spring-boot-starter-web", "B": "spring-boot-starter-jdbc", "C": "spring-boot-starter-data-jpa", "D": "spring-boot-starter-thymeleaf"}, "correct": "C", "correctText": "spring-boot-starter-data-jpa", "explanation": "spring-boot-starter-data-jpa tích hợp Spring Data JPA, Hibernate cùng cơ chế repository để thao tác database quan hệ từ entity."}, {"id": 280, "label": "Câu 280", "question": "Which JPA feature avoids writing SQL manually?", "choices": {"A": "HQL", "B": "Native queries", "C": "Method name queries", "D": "ORM generator"}, "correct": "C", "correctText": "Method name queries", "explanation": "Spring Data suy ra truy vấn từ tên method như findByNam eAndAgeGr eaterThan, giảm nhu cầu viết SQL/JPQL thủ công cho trường hợp thông dụng."}, {"id": 281, "label": "Câu 281", "question": "Which relationship is many-to-one?", "choices": {"A": "@OneToOne", "B": "@OneToMany", "C": "@ManyToOne", "D": "@ManyToMany"}, "correct": "C", "correctText": "@ManyToOne", "explanation": "@ManyToOne cho biết nhiều bản ghi entity này có thể tham chiếu một bản ghi entity khác, thường qua một foreign key."}, {"id": 282, "label": "Câu 282", "question": "Which relationship uses a join table?", "choices": {"A": "One-to-one", "B": "Many-to-one", "C": "Many-to-many", "D": "One-to-many"}, "correct": "C", "correctText": "Many-to-many", "explanation": "Many-to-many thường dùng bảng nối gồm hai khóa ngoại, mỗi dòng biểu diễn một liên kết giữa hai entity."}, {"id": 283, "label": "Câu 283", "question": "CascadeType.ALL means:", "choices": {"A": "No cascading", "B": "Only save cascades", "C": "All operations cascade", "D": "Delete only"}, "correct": "C", "correctText": "All operations cascade", "explanation": "CascadeType.ALL áp dụng tất cả thao tác cascade chuẩn như PERSIST, MERGE, REMOVE, REFRESH và DETACH từ entity cha sang entity liên quan."}, {"id": 284, "label": "Câu 284", "question": "Spring Boot auto-configures beans using:", "choices": {"A": "@EnableAutoConfiguration", "B": "@AutoBean", "C": "@SpringBootApplication", "D": "@AutoScan"}, "correct": "C", "correctText": "@SpringBootApplication", "explanation": "@SpringBootApplication gồm @SpringBootConfiguration, @EnableAutoConfiguration và @ComponentScan; auto-configuration tạo bean theo dependency và điều kiện cấu hình."}, {"id": 285, "label": "Câu 285", "question": "Paging in Spring Boot is implemented using:", "choices": {"A": "PageRequest", "B": "OffsetManager", "C": "PageBuilder", "D": "PageableFactory"}, "correct": "A", "correctText": "PageRequest", "explanation": "PageRequest.of(page, size) tạo Pageable chứa số trang (bắt đầu từ 0) và kích thước trang để truyền vào repository."}, {"id": 286, "label": "Câu 286", "question": "Sorting in Spring Boot is achieved via:", "choices": {"A": "Sort.by()", "B": "Sort.order()", "C": "Sort.new()", "D": "SortList()"}, "correct": "A", "correctText": "Sort.by()", "explanation": "Sort.by(\"field\") tạo chỉ dẫn sắp xếp, mặc định tăng dần; có thể đổi thành descending() khi cần."}, {"id": 287, "label": "Câu 287", "question": "What is a primary advantage of Single Page Applications (SPAs) compared to traditional multi-page applications?", "choices": {"A": "They offer faster transitions between pages after the first load", "B": "They require no JavaScript", "C": "They offer faster initial page loads", "D": "They reduce server-side processing for all requests"}, "correct": "A", "correctText": "They offer faster transitions between pages after the first load", "explanation": "Sau lần tải ban đầu, SPA đổi view ở client nên điều hướng thường nhanh hơn và không phải tải lại cả tài liệu HTML."}, {"id": 288, "label": "Câu 288", "question": "What does ResponseEntity provide in a REST controller method?", "choices": {"A": "A flexible way to set body, status, and headers", "B": "Only status codes", "C": "A way to redirect to views", "D": "Only body"}, "correct": "A", "correctText": "A flexible way to set body, status, and headers", "explanation": "ResponseEntity cho phép điều chỉnh cả response body, HTTP status và headers theo từng nhánh, ví dụ ResponseEntity.status(201).body(obj)."}, {"id": 289, "label": "Câu 289", "question": "What is a key advantage of using MongoTemplate?", "choices": {"A": "Automatic generation of CRUD methods.", "B": "Flexibility for complex queries and operations.", "C": "Simplified data model definition.", "D": "Built-in transaction management."}, "correct": "B", "correctText": "Flexibility for complex queries and operations.", "explanation": "MongoTemplate cho phép dùng Query, Criteria và các thao tác cập nhật phức tạp. MongoRepository thuận tiện hơn cho CRUD đơn giản."}, {"id": 290, "label": "Câu 290", "question": "Which method in MongoTemplate is used to insert a single document?", "choices": {"A": "save()", "B": "insert()", "C": "create()", "D": "add()"}, "correct": "B", "correctText": "insert()", "explanation": "mongoTemplate.insert(object) tạo một document mới. Khác với save(), insert() không dùng để ghi đè document có cùng ID."}, {"id": 291, "label": "Câu 291", "question": "Which MongoDB command is used to delete documents from a collection?", "choices": {"A": "update()", "B": "find()", "C": "insertOne()", "D": "deleteMany() or deleteOne()"}, "correct": "D", "correctText": "deleteMany() or deleteOne()", "explanation": "deleteOne() xóa một document khớp điều kiện, còn deleteMany() xóa tất cả document khớp. find() chỉ truy vấn dữ liệu."}, {"id": 292, "label": "Câu 292", "question": "What does the spring-boot-starter-data-mongodb dependency include?", "choices": {"A": "Only the MongoDB Java driver.", "B": "The MongoDB Java driver and Spring Data MongoDB.", "C": "Only Spring Data MongoDB.", "D": "JDBC drivers and Spring Data JPA."}, "correct": "B", "correctText": "The MongoDB Java driver and Spring Data MongoDB.", "explanation": "Starter MongoDB kéo vào Spring Data MongoDB và MongoDB Java Driver để ứng dụng Spring Boot ánh xạ object và giao tiếp với MongoDB."}, {"id": 293, "label": "Câu 293", "question": "What is MongoDB Atlas?", "choices": {"A": "A local installation of MongoDB.", "B": "A cloud-hosted database service by MongoDB.", "C": "A Java driver for MongoDB.", "D": "A tool for managing relational databases."}, "correct": "B", "correctText": "A cloud-hosted database service by MongoDB.", "explanation": "MongoDB Atlas cung cấp cluster MongoDB được quản lý trên cloud, hỗ trợ triển khai, sao lưu, giám sát và kết nối từ xa."}, {"id": 294, "label": "Câu 294", "question": "While MongoRepository is great for CRUD operations, which class offers more fine-grained control for executing complex queries and operations against MongoDB?", "choices": {"A": "MongoTemplate", "B": "MongoExecutor", "C": "JdbcTemplate", "D": "MongoManager"}, "correct": "A", "correctText": "MongoTemplate", "explanation": "MongoTemplate hỗ trợ Criteria, aggregation và cập nhật tùy biến; MongoRepository chủ yếu cung cấp các hàm CRUD và derived queries."}, {"id": 295, "label": "Câu 295", "question": "Which MongoDB command is used to retrieve documents from a collection?", "choices": {"A": "update()", "B": "find()", "C": "insertOne()", "D": "deleteMany()"}, "correct": "B", "correctText": "find()", "explanation": "find() trả về các document phù hợp bộ lọc trong collection; có thể kết hợp projection, sort và limit."}, {"id": 296, "label": "Câu 296", "question": "Which class in Spring Data MongoDB provides a template for performing low-level MongoDB operations?", "choices": {"A": "MongoRepository", "B": "MongoClient", "C": "MongoTemplate", "D": "SimpleMongoRepository"}, "correct": "C", "correctText": "MongoTemplate", "explanation": "MongoTemplate là lớp thao tác MongoDB ở mức thấp hơn Repository, hỗ trợ Query, Criteria, aggregation và các lệnh cập nhật tùy biến."}, {"id": 297, "label": "Câu 297", "question": "When configuring the connection string for MongoDB Atlas in Spring Boot, what is the purpose of including the username and password?", "choices": {"A": "To specify the local database path.", "B": "To authenticate the application with the MongoDB Atlas cluster.", "C": "To configure the JDBC driver.", "D": "To define the data model."}, "correct": "B", "correctText": "To authenticate the application with the MongoDB Atlas cluster.", "explanation": "Username và password trong MongoDB URI được driver dùng để xác thực với cluster Atlas; đây không phải thông số JDBC hay vị trí tệp database."}, {"id": 298, "label": "Câu 298", "question": "What is a collection in MongoDB?", "choices": {"A": "A single document", "B": "A group of related documents", "C": "A database server", "D": "A query result"}, "correct": "B", "correctText": "A group of related documents", "explanation": "Collection trong MongoDB là tập các document, gần giống bảng trong SQL nhưng các document không bắt buộc có cùng bộ field."}, {"id": 299, "label": "Câu 299", "question": "How does MongoRepository simplify data access?", "choices": {"A": "Complex aggregations", "B": "Auto-generate CRUD methods", "C": "Manage DB connection", "D": "Handle BSON manually"}, "correct": "B", "correctText": "Auto-generate CRUD methods", "explanation": "MongoRepository tự cung cấp các phương thức CRUD và cho phép suy ra query từ tên method, giảm lượng code truy cập database phải viết."}, {"id": 300, "label": "Câu 300", "question": "Which MongoDB structure stores documents?", "choices": {"A": "Table", "B": "Collection", "C": "Schema", "D": "Sequence"}, "correct": "B", "correctText": "Collection", "explanation": "Collection chứa nhiều document MongoDB; mỗi document là một bản ghi dạng BSON có thể chứa các field khác nhau."}, {"id": 301, "label": "Câu 301", "question": "MongoDB stores data in:", "choices": {"A": "Rows", "B": "Nodes", "C": "JSON-like documents", "D": "CSV files"}, "correct": "C", "correctText": "JSON-like documents", "explanation": "MongoDB lưu document ở dạng BSON, một định dạng nhị phân tương tự JSON nhưng hỗ trợ thêm kiểu như ObjectId và Date."}, {"id": 302, "label": "Câu 302", "question": "Which MongoDB CRUD operation inserts a document?", "choices": {"A": "updateOne()", "B": "deleteOne()", "C": "insertOne()", "D": "findOne()"}, "correct": "C", "correctText": "insertOne()", "explanation": "insertOne() thêm một document mới vào collection; nếu không cung cấp _id, MongoDB driver có thể tự tạo ObjectId."}, {"id": 303, "label": "Câu 303", "question": "Which MongoDB method retrieves all documents?", "choices": {"A": "find()", "B": "findOne()", "C": "getAll()", "D": "select()"}, "correct": "A", "correctText": "find()", "explanation": "find({}) truy xuất các document trong collection MongoDB; dấu ngoặc nhọn rỗng nghĩa là không áp dụng điều kiện lọc."}, {"id": 304, "label": "Câu 304", "question": "Which data type does MongoDB use for date?", "choices": {"A": "String", "B": "ISODate", "C": "LocalDate", "D": "Timestamp"}, "correct": "B", "correctText": "ISODate", "explanation": "MongoDB có kiểu Date trong BSON; shell thường hiển thị hoặc tạo giá trị ngày bằng ISODate(), lưu mốc thời gian UTC."}, {"id": 305, "label": "Câu 305", "question": "Which MongoDB operator filters by range?", "choices": {"A": "$eq", "B": "$range", "C": "$gt / $lt", "D": "$match"}, "correct": "C", "correctText": "$gt / $lt", "explanation": "$gt lọc lớn hơn một giá trị, $lt lọc nhỏ hơn; kết hợp cả hai giúp tìm tài liệu trong một khoảng."}, {"id": 306, "label": "Câu 306", "question": "Which MongoDB aggregation stage groups documents?", "choices": {"A": "$group", "B": "$sum", "C": "$sort", "D": "$match"}, "correct": "A", "correctText": "$group", "explanation": "Stage $group gom document theo khóa _id và tính các giá trị tổng hợp như $sum, $avg và $count."}, {"id": 307, "label": "Câu 307", "question": "Which database type does MongoDB represent?", "choices": {"A": "Relational", "B": "Document-oriented", "C": "Graph", "D": "In-memory"}, "correct": "B", "correctText": "Document-oriented", "explanation": "MongoDB là NoSQL document database, lưu dữ liệu dưới dạng các document BSON trong collection thay vì hàng/cột cố định."}, {"id": 308, "label": "Câu 308", "question": "Which Spring Data interface works with MongoDB?", "choices": {"A": "JpaRepository", "B": "CrudRepository", "C": "MongoRepository", "D": "HibernateRepository"}, "correct": "C", "correctText": "MongoRepository", "explanation": "MongoRepository là interface repository cho entity MongoDB, hỗ trợ CRUD, phân trang và các truy vấn dẫn xuất từ tên method."}, {"id": 309, "label": "Câu 309", "question": "Which operator selects documents matching multiple conditions?", "choices": {"A": "$or", "B": "$and", "C": "$eq", "D": "$join"}, "correct": "B", "correctText": "$and", "explanation": "$and yêu cầu tất cả điều kiện con cùng đúng; MongoDB cũng thường hiểu AND ngầm khi nhiều field nằm trong cùng filter object."}, {"id": 310, "label": "Câu 310", "question": "Which command deletes multiple MongoDB documents?", "choices": {"A": "deleteOne()", "B": "deleteMany()", "C": "remove()", "D": "drop()"}, "correct": "B", "correctText": "deleteMany()", "explanation": "deleteMany(filter) xóa tất cả document khớp filter; deleteOne(filter) chỉ xóa một document khớp."}, {"id": 311, "label": "Câu 311", "question": "What is the purpose of the @DBRef annotation in Spring Data MongoDB?", "choices": {"A": "To map embedded documents", "B": "To index a document", "C": "To define a relationship between documents via reference", "D": "To ignore the field during persistence"}, "correct": "C", "correctText": "To define a relationship between documents via reference", "explanation": "@DBRef lưu tham chiếu đến document khác thay vì nhúng toàn bộ; cần cân nhắc truy vấn bổ sung và chi phí tải các liên kết."}, {"id": 312, "label": "Câu 312", "question": "How does MongoDB ensure high availability with replication?", "choices": {"A": "By using SQL mirroring", "B": "By using cron jobs for backup", "C": "Through replica sets with automatic failover", "D": "By distributing indexes across servers"}, "correct": "C", "correctText": "Through replica sets with automatic failover", "explanation": "Replica set có một primary và các secondary sao chép oplog; nếu primary lỗi, các node đủ điều kiện có thể bầu primary mới để tiếp tục hoạt động."}, {"id": 313, "label": "Câu 313", "question": "In Spring Boot, which starter dependency is used to include MongoDB support?", "choices": {"A": "spring-boot-mongodb", "B": "spring-boot-starter-data-mongodb", "C": "spring-boot-starter-data-jpa", "D": "spring-boot-starter-mongo"}, "correct": "B", "correctText": "spring-boot-starter-data-mongodb", "explanation": "spring-boot-starter-data-mongodb đưa Spring Data MongoDB và driver vào ứng dụng, hỗ trợ MongoRepository và MongoTemplate."}, {"id": 314, "label": "Câu 314", "question": "Which command is used to insert a single document into a collection?", "choices": {"A": "db.collection.create()", "B": "db.collection.insertOne()", "C": "db.collection.insertDocument()", "D": "db.collection.add()"}, "correct": "B", "correctText": "db.collection.insertOne()", "explanation": "db.collection.insertOne(document) thêm chính xác một document mới; MongoDB sẽ cấp _id nếu chưa có."}, {"id": 315, "label": "Câu 315", "question": "What does the MongoTemplate class provide in Spring Data MongoDB?", "choices": {"A": "Mapping of SQL queries to documents", "B": "Automatic index creation", "C": "A low-level interface to MongoDB operations", "D": "Automatic data validation"}, "correct": "C", "correctText": "A low-level interface to MongoDB operations", "explanation": "MongoTemplate cho API cấp thấp hơn repository với Query, Criteria, update và aggregation, hỗ trợ truy vấn phức tạp trên MongoDB."}, {"id": 316, "label": "Câu 316", "question": "Which class is used to create complex criteria queries with MongoTemplate?", "choices": {"A": "Criteria", "B": "QueryDSL", "C": "MongoQuery", "D": "CriteriaBuilder"}, "correct": "A", "correctText": "Criteria", "explanation": "Criteria biểu diễn điều kiện lọc như where(\"age\").gte(18); ghép Criteria vào Query rồi đưa cho MongoTemplate.find()."}, {"id": 317, "label": "Câu 317", "question": "Which annotation is used to define a MongoDB document in Spring Data MongoDB?", "choices": {"A": "@Collection", "B": "@MongoEntity", "C": "@Document", "D": "@Entity"}, "correct": "C", "correctText": "@Document", "explanation": "@Document chỉ định lớp Java ánh xạ thành document MongoDB và có thể quy định tên collection qua thuộc tính collection."}, {"id": 318, "label": "Câu 318", "question": "Which interface in Spring Data MongoDB is used to perform CRUD operations?", "choices": {"A": "JpaRepository", "B": "MongoRepository", "C": "Repository", "D": "CrudRepository"}, "correct": "B", "correctText": "MongoRepository", "explanation": "MongoRepository mở rộng repository Spring Data để cung cấp CRUD theo entity MongoDB, hỗ trợ tìm kiếm theo method name."}, {"id": 319, "label": "Câu 319", "question": "Which of the following best describes a compound index?", "choices": {"A": "An index with a TTL (Time To Live)", "B": "A temporary index created at runtime", "C": "An index on an embedded document only", "D": "An index on multiple fields in a document"}, "correct": "D", "correctText": "An index on multiple fields in a document", "explanation": "Compound index lập chỉ mục theo nhiều field có thứ tự, ví dụ {name:1, age:1}; thứ tự field ảnh hưởng truy vấn có thể tận dụng index."}, {"id": 320, "label": "Câu 320", "question": "Which property is used in application.properties to set the MongoDB database name?", "choices": {"A": "spring.data.mongo.name", "B": "spring.mongodb.dbname", "C": "spring.data.mongodb.database", "D": "spring.mongo.database"}, "correct": "C", "correctText": "spring.data.mongodb.database", "explanation": "spring.data.mongodb.database chỉ định tên database mặc định cho kết nối Spring Data MongoDB nếu không được chọn theo cấu hình khác."}, {"id": 321, "label": "Câu 321", "question": "When using MongoTemplate, how would you insert a new document?", "choices": {"A": "mongoTemplate.create(object)", "B": "mongoTemplate.insert(object)", "C": "mongoTemplate.save(object)", "D": "mongoTemplate.add(object)"}, "correct": "C", "correctText": "mongoTemplate.save(object)", "explanation": "mongoTemplate.save(object) thêm mới nếu chưa có document phù hợp ID, hoặc cập nhật/ thay thế nếu ID đã tồn tại; insert() thì chỉ dùng để thêm."}, {"id": 322, "label": "Câu 322", "question": "Which of the following is used to create an index on a field in MongoDB?", "choices": {"A": "db.collection.setIndex()", "B": "db.collection.index()", "C": "db.collection.createIndex()", "D": "db.collection.makeIndex()"}, "correct": "C", "correctText": "db.collection.createIndex()", "explanation": "db.collection.createIndex({field:1}) tạo chỉ mục tăng dần cho field, giúp một số filter và sort nhanh hơn nhưng có chi phí lưu trữ/ ghi."}, {"id": 323, "label": "Câu 323", "question": "In MongoDB, which of the following allows for joining documents from two collections?", "choices": {"A": "$merge", "B": "$match", "C": "$unwind", "D": "$lookup"}, "correct": "D", "correctText": "$lookup", "explanation": "Aggregation stage $lookup thực hiện phép nối kiểu left outer join với collection khác, đưa các document khớp vào một field mảng."}, {"id": 324, "label": "Câu 324", "question": "Which of the following is TRUE about MongoDB schema?", "choices": {"A": "MongoDB supports relational schema only", "B": "Collections in MongoDB can have documents with different fields", "C": "MongoDB requires a fixed schema", "D": "All fields in documents must be predefined"}, "correct": "B", "correctText": "Collections in MongoDB can have documents with different fields", "explanation": "MongoDB có schema linh hoạt: các document trong cùng collection có thể khác field hoặc cấu trúc; vẫn có thể bật schema validation nếu cần."}, {"id": 325, "label": "Câu 325", "question": "Which of the following is used to return only selected fields in a MongoDB query?", "choices": {"A": "$select", "B": "ReturnFields", "C": "Projection", "D": "Subset"}, "correct": "C", "correctText": "Projection", "explanation": "Projection chỉ định field nào được trả về hoặc loại khỏi kết quả find(), giúp giảm dữ liệu truyền và xử lý."}, {"id": 326, "label": "Câu 326", "question": "Which index type is used to ensure that a field's value is unique across documents?", "choices": {"A": "Compound index", "B": "Unique index", "C": "Hashed index", "D": "Text index"}, "correct": "B", "correctText": "Unique index", "explanation": "Unique index yêu cầu giá trị khóa chỉ mục không trùng nhau giữa các document được áp dụng chỉ mục, giúp ngăn dữ liệu trùng."}, {"id": 327, "label": "Câu 327", "question": "Which Spring Boot module provides support for integration testing?", "choices": {"A": "spring-boot-starter-web", "B": "spring-boot-starter-data-jpa", "C": "spring-boot-starter-test", "D": "spring-boot-starter-security"}, "correct": "C", "correctText": "spring-boot-starter-test", "explanation": "spring-boot-starter-test bao gồm JUnit, Spring Test, AssertJ và công cụ hỗ trợ kiểm thử, dùng cho unit và integration test."}, {"id": 328, "label": "Câu 328", "question": "Which type of testing verifies the functionality of individual units of code?", "choices": {"A": "Integration testing.", "B": "End-to-end testing.", "C": "Unit testing.", "D": "Performance testing."}, "correct": "C", "correctText": "Unit testing.", "explanation": "Unit test kiểm tra một hàm, lớp hoặc thành phần nhỏ trong điều kiện cô lập; integration test kiểm tra nhiều thành phần phối hợp."}, {"id": 329, "label": "Câu 329", "question": "Tool for testing REST?", "choices": {"A": "React DevTools", "B": "Postman", "C": "Bootstrap", "D": "Axios"}, "correct": "B", "correctText": "Postman", "explanation": "Postman cho phép gửi HTTP requests với method, header, body và xem response, thuận tiện kiểm thử API trước khi tích hợp frontend."}, {"id": 330, "label": "Câu 330", "question": "What is the purpose of @SpringBootTest annotation?", "choices": {"A": "Mock dependencies", "B": "Run unit tests", "C": "Load full Spring context for integration tests", "D": "Define data models"}, "correct": "C", "correctText": "Load full Spring context for integration tests", "explanation": "@SpringBootTest khởi tạo Spring Application Context cho integration test, cho phép kiểm thử các bean và cấu hình cùng hoạt động."}, {"id": 331, "label": "Câu 331", "question": "What does @SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT) do?", "choices": {"A": "Starts the application with no web environment", "B": "Fails the test if no port is provided manually", "C": "Disables the web server", "D": "Starts the embedded server on a random port"}, "correct": "D", "correctText": "Starts the embedded server on a random port", "explanation": "WebEnvironment.RANDOM_PORT khởi động web server nhúng trên cổng ngẫu nhiên, hữu ích để integration test qua HTTP mà tránh đụng cổng."}, {"id": 332, "label": "Câu 332", "question": "You want to inject a TestRestTemplate in a @SpringBootTest. What is required?", "choices": {"A": "Use @MockBean", "B": "Use webEnvironment = WebEnvironment.NONE", "C": "Use @WebMvcTest", "D": "Use webEnvironment = WebEnvironment.RANDOM_PORT"}, "correct": "D", "correctText": "Use webEnvironment = WebEnvironment.RANDOM_PORT", "explanation": "TestRestTemplate thường được cung cấp khi @SpringBootTest chạy với môi trường web thực như RANDOM_PORT, để test gửi HTTP request đến server nhúng."}, {"id": 333, "label": "Câu 333", "question": "When used with JUnit 5, which annotation is commonly paired with @SpringBootTest?", "choices": {"A": "@MockBean", "B": "@ExtendWith(SpringExtension.class)", "C": "@DataJpaTest", "D": "@TestConfiguration"}, "correct": "B", "correctText": "@ExtendWith(SpringExtension.class)", "explanation": "SpringExtension tích hợp Spring TestContext với JUnit Jupiter; @SpringBootTest hiện đã tự đăng ký extension này nên thường không cần thêm @ExtendWith thủ công."}, {"id": 334, "label": "Câu 334", "question": "Which configuration allows @SpringBootTest to test controller endpoints using real HTTP calls?", "choices": {"A": "webEnvironment = NONE", "B": "webEnvironment = MOCK", "C": "useMockMvc = true", "D": "webEnvironment = DEFINED_PORT"}, "correct": "D", "correctText": "webEnvironment = DEFINED_PORT", "explanation": "DEFINED_PORT khởi chạy web server trên cổng cấu hình nên có thể test endpoint qua HTTP thực; RANDOM_PORT cũng hỗ trợ kiểu test này và tránh xung đột cổng."}, {"id": 335, "label": "Câu 335", "question": "Which of the following annotations can be used instead of @SpringBootTest for testing only the web layer?", "choices": {"A": "@Configuration", "B": "@DataJpaTest", "C": "@WebMvcTest", "D": "@EnableAutoConfiguration"}, "correct": "C", "correctText": "@WebMvcTest", "explanation": "@WebMvcTest chỉ nạp các thành phần Spring MVC như controller, converter và hỗ trợ MockMvc, nhanh hơn test toàn bộ context bằng @SpringBootTest."}, {"id": 336, "label": "Câu 336", "question": "Which command is used to create a new branch called \"feature-login\"?", "choices": {"A": "git branch create feature-login", "B": "git new branch feature-login", "C": "git branch feature-login", "D": "git checkout feature-login"}, "correct": "C", "correctText": "git branch feature-login", "explanation": "git branch feature-login tạo nhánh mới nhưng không tự chuyển sang nhánh đó. Muốn vừa tạo vừa chuyển có thể dùng git switch -c feature-login."}];
